export default {
  subjectId: "english-literature",
  sections: {
    "An Inspector Calls": [
      // GRADE 4
      { g: 4, marks: 1, q: "Who wrote An Inspector Calls?", scheme: ["J.B. Priestley"], answer: "J.B. Priestley." },
      { g: 4, marks: 1, q: "Who is the mysterious visitor who questions the family?", scheme: ["Inspector Goole"], answer: "Inspector Goole." },
      { g: 4, marks: 1, q: "What is the surname of the family in the play?", scheme: ["The Birlings"], answer: "The Birlings." },
      { g: 4, marks: 1, q: "Who is engaged to be married at the start?", scheme: ["Sheila Birling and Gerald Croft"], answer: "Sheila Birling and Gerald Croft." },
      { g: 4, marks: 1, q: "What is the name of the girl who died?", scheme: ["Eva Smith (also known as Daisy Renton)"], answer: "Eva Smith (also called Daisy Renton)." },
      { g: 4, marks: 1, q: "How did Eva Smith die?", scheme: ["She drank disinfectant / took her own life"], answer: "She took her own life by drinking disinfectant." },
      { g: 4, marks: 1, q: "What is Mr Birling's job?", scheme: ["A wealthy factory owner / businessman"], answer: "He is a wealthy factory owner and businessman." },
      { g: 4, marks: 1, q: "In what year is the play set?", scheme: ["1912"], answer: "1912." },
      { g: 4, marks: 1, q: "When was the play written and first performed?", scheme: ["1945"], answer: "1945." },
      { g: 4, marks: 1, q: "What type of play is An Inspector Calls often called?", scheme: ["A morality play"], answer: "A morality play." },
      // GRADE 5
      { g: 5, marks: 2, q: "Describe Mr Birling's views at the start of the play.", scheme: ["A selfish capitalist", "Believes 'a man has to look after himself'"], answer: "He is a selfish capitalist who believes a man should only look after himself and his own family." },
      { g: 5, marks: 1, q: "Describe the Inspector's role in the play.", scheme: ["Questions each character about their part in Eva's death; a moral force"], answer: "He questions each character about how they contributed to Eva's death, acting as a moral force." },
      { g: 5, marks: 1, q: "Describe how Mr Birling was responsible for Eva Smith.", scheme: ["He sacked her for asking for higher wages"], answer: "He sacked her from his factory for leading a request for higher wages." },
      { g: 5, marks: 1, q: "Describe how Sheila was responsible for Eva Smith.", scheme: ["She had Eva sacked from a shop out of jealousy"], answer: "She had Eva dismissed from a shop out of jealousy and spite." },
      { g: 5, marks: 1, q: "Describe how Gerald was involved with Eva Smith.", scheme: ["He had an affair with her (as Daisy Renton)"], answer: "He had an affair with her while she was calling herself Daisy Renton." },
      { g: 5, marks: 2, q: "Describe how Mrs Birling was responsible for Eva Smith.", scheme: ["She refused Eva help from her charity", "When Eva was pregnant and desperate"], answer: "As head of a charity, she refused to help Eva when she came for support while pregnant and desperate." },
      { g: 5, marks: 2, q: "Describe how Eric was involved with Eva Smith.", scheme: ["He had a relationship with her; she became pregnant", "He stole money to help her"], answer: "He had a relationship with Eva that left her pregnant, and he stole money from his father's firm to help her." },
      { g: 5, marks: 1, q: "Describe the main message of the play.", scheme: ["We are all responsible for one another (social responsibility)"], answer: "That everyone is responsible for one another and for how their actions affect others." },
      { g: 5, marks: 1, q: "Describe the twist at the very end of the play.", scheme: ["A phone call says a real inspector is on his way about a girl's death"], answer: "A phone call reveals that a real inspector is on his way to ask about the death of a girl." },
      { g: 5, marks: 2, q: "Describe the difference between the older and younger Birlings.", scheme: ["The young (Sheila/Eric) accept responsibility", "The older Birlings refuse to change"], answer: "The younger Sheila and Eric accept responsibility and are changed, while the older Birlings refuse to accept blame or change." },
      // GRADE 6
      { g: 6, marks: 3, q: "Explain how Priestley presents Mr Birling.", scheme: ["A selfish, arrogant capitalist", "Dismisses social responsibility", "Made foolish through dramatic irony"], answer: "Priestley presents Mr Birling as a selfish, arrogant capitalist who dismisses social responsibility, and undermines him through dramatic irony that makes his confident opinions look foolish." },
      { g: 6, marks: 3, q: "Explain how Priestley uses dramatic irony through Mr Birling.", scheme: ["Birling calls the Titanic 'unsinkable'", "He says war is impossible", "The 1945 audience knows he is wrong, so his views are undermined"], answer: "Birling confidently claims the Titanic is unsinkable and that there will be no war, but the 1945 audience knows both were catastrophically wrong, so Priestley uses dramatic irony to discredit his views." },
      { g: 6, marks: 3, q: "Explain the Inspector's final speech and its message.", scheme: ["'We are members of one body'", "Warning of 'fire and blood and anguish' if lessons aren't learned", "Message of collective responsibility"], answer: "In his final speech the Inspector warns that 'we are members of one body' and that if people do not learn responsibility they will be taught it 'in fire and blood and anguish', delivering Priestley's message of collective responsibility." },
      { g: 6, marks: 2, q: "Explain how Sheila changes during the play.", scheme: ["Becomes aware and guilty", "Accepts responsibility; challenges her parents"], answer: "Sheila becomes aware of her guilt, accepts responsibility for her part in Eva's death, and by the end challenges her parents' refusal to change." },
      { g: 6, marks: 2, q: "Explain how Eric changes during the play.", scheme: ["Becomes ashamed and accepts guilt", "Criticises his parents' attitude"], answer: "Eric becomes ashamed, openly accepts his guilt, and criticises his parents for refusing to accept responsibility." },
      { g: 6, marks: 2, q: "Explain why the older Birlings do not change.", scheme: ["They care about reputation and status", "They refuse to accept responsibility"], answer: "The older Birlings care mainly about their reputation and status, so they refuse to accept responsibility and are relieved when they think the Inspector was a hoax." },
      { g: 6, marks: 2, q: "Explain the significance of the Inspector's name, 'Goole'.", scheme: ["Homophone of 'ghoul'", "Suggests a supernatural/otherworldly, moral force"], answer: "'Goole' sounds like 'ghoul', suggesting the Inspector is a supernatural or otherworldly figure, a moral force rather than an ordinary policeman." },
      { g: 6, marks: 3, q: "Explain how the play criticises capitalism.", scheme: ["Mr Birling embodies selfish capitalism, made to look foolish", "Eva's exploitation shows the harm capitalism causes", "The Inspector offers a socialist alternative"], answer: "Priestley criticises capitalism through the foolish, selfish Mr Birling and the way Eva is exploited by the wealthy, contrasting this with the Inspector's socialist message of caring for one another." },
      { g: 6, marks: 2, q: "Explain the significance of setting the play in 1912 for a 1945 audience.", scheme: ["Dramatic irony/hindsight (Titanic, wars)", "Contrasts the divided pre-war world with 1945 hopes for change"], answer: "The 1912 setting lets the 1945 audience use hindsight to see how wrong Birling's views were, and contrasts the divided pre-war world with the audience's hopes for a fairer society after the war." },
      { g: 6, marks: 2, q: "Explain how Eva Smith works as a symbol in the play.", scheme: ["Represents the working class / the vulnerable poor", "We never see her — she stands for all such people"], answer: "Eva Smith represents the working class and the vulnerable poor, and because we never actually see her she stands for all the ordinary people mistreated by the powerful." },
      // GRADE 7
      { g: 7, marks: 4, q: "Analyse how Priestley uses the Inspector as a dramatic device.", scheme: ["Controls the pace, revealing information one at a time", "Acts as Priestley's mouthpiece / moral authority", "Interrogates and exposes each character", "His name and knowledge suggest a supernatural role"], answer: "Priestley uses the Inspector to control the play's pace, revealing the story one character at a time, and as his own mouthpiece with moral authority who interrogates and exposes each Birling. His name 'Goole' and his uncanny knowledge suggest he is more than a real policeman — a moral, almost supernatural force." },
      { g: 7, marks: 4, q: "Analyse how Priestley presents Sheila as a voice of change.", scheme: ["Begins naive and materialistic", "Quickly accepts guilt and responsibility", "Sees through the Inspector's purpose and warns her parents", "Represents hope and the younger generation"], answer: "Sheila begins naive and materialistic but quickly accepts her guilt and responsibility, and unlike her parents she understands the Inspector's purpose and warns them not to try to escape it. She becomes a voice of change, representing Priestley's hope in the younger generation." },
      { g: 7, marks: 4, q: "Analyse how Priestley presents Mrs Birling's cold attitude.", scheme: ["Snobbish and dismissive of the lower classes", "Refuses Eva charity and blames the father", "Ironically condemns her own son", "Shows no remorse"], answer: "Priestley presents Mrs Birling as snobbish and dismissive of the poor, refusing Eva charity and demanding the child's father be punished — dramatically ironic as it is her own son. Her lack of remorse exposes the cold heartlessness Priestley criticises in the upper classes." },
      { g: 7, marks: 4, q: "Analyse how Priestley explores the theme of class in the play.", scheme: ["The wealthy Birlings exploit the working-class Eva", "The Birlings look down on the lower classes", "The Inspector challenges class prejudice", "Eva symbolises the exploited working class"], answer: "Priestley explores class through the way the wealthy Birlings exploit and look down on the working-class Eva, whom each of them harms, while the Inspector challenges their class prejudice. Eva becomes a symbol of the exploited working class, criticising the injustice of a divided society." },
      { g: 7, marks: 4, q: "Analyse how Priestley presents gender in the play.", scheme: ["Eva is vulnerable partly because she is a poor woman", "Sheila and Eva contrast (power and privilege)", "Men (Gerald, Eric) exploit Eva", "Attitudes of the time towards women"], answer: "Priestley shows Eva as doubly vulnerable as a poor woman, exploited by men such as Gerald and Eric, and contrasts her powerlessness with Sheila's privilege. Through this he exposes the unequal and unfair treatment of women in the society of the time." },
      { g: 7, marks: 3, q: "Analyse how Priestley builds tension throughout the play.", scheme: ["The Inspector reveals information gradually (one photo at a time)", "Interruptions and cliffhangers", "Growing conflict within the family"], answer: "Priestley builds tension by having the Inspector reveal the story gradually, showing the photograph to one character at a time, and through interruptions, cliffhangers and the growing conflict within the family as each secret is exposed." },
      { g: 7, marks: 4, q: "Analyse how Priestley presents the generational divide.", scheme: ["Older Birlings (Mr and Mrs) refuse to change", "Younger (Sheila and Eric) accept responsibility", "Gerald is in between", "Suggests hope lies with the young"], answer: "Priestley presents a clear divide: the older Birlings refuse to accept responsibility and cling to reputation, while the younger Sheila and Eric accept their guilt and want to change. Gerald sits between the two, and overall Priestley suggests hope for a fairer future lies with the younger generation." },
      { g: 7, marks: 3, q: "Analyse how Priestley presents Gerald's character.", scheme: ["Charming and upper-class", "Genuinely cared for Eva in some ways but still used her", "Sides with the older generation at the end"], answer: "Priestley presents Gerald as charming and upper-class, and while he showed Eva some genuine kindness he still used her and abandoned her. At the end he sides with the older Birlings in trying to escape responsibility, showing he has not truly changed." },
      { g: 7, marks: 4, q: "Analyse how the play works as a morality play.", scheme: ["The Inspector acts like a moral judge", "Each character is examined for their 'sin'", "The message teaches the audience a moral lesson", "Warns of consequences"], answer: "The play works as a morality play because the Inspector acts as a moral judge, examining each character's 'sin' against Eva, and the whole play teaches the audience the moral lesson of social responsibility, warning of the consequences if it is ignored." },
      { g: 7, marks: 3, q: "Analyse how Priestley uses dramatic irony to shape the audience's view.", scheme: ["Birling's wrong predictions (Titanic, war)", "Positions the audience against his capitalist views", "Encourages support for the Inspector's message"], answer: "Through Birling's confidently wrong predictions about the Titanic and war, Priestley uses dramatic irony to make the audience distrust his capitalist views and instead sympathise with the Inspector's message of responsibility." },
      // GRADE 8
      { g: 8, marks: 5, q: "'The Inspector is the most important character in the play.' How far do you agree?", scheme: ["He drives the plot and delivers the message", "Acts as Priestley's mouthpiece/moral force", "But the Birlings' reactions matter too", "Balanced, supported judgement"], answer: "The Inspector is hugely important as he drives the plot, exposes each character and delivers Priestley's message as his mouthpiece and moral force. However, the Birlings' contrasting reactions are also essential to the play's meaning, so while the Inspector is arguably the most important character, the play depends on the whole family's responses." },
      { g: 8, marks: 5, q: "Analyse how far the Birlings are presented as responsible for Eva's death.", scheme: ["Each character contributed a link in the 'chain of events'", "Priestley shows collective responsibility", "Some (older) refuse to accept it", "Judgement — all share responsibility"], answer: "Priestley presents each Birling as adding a link in the chain of events that led to Eva's death, so they are collectively responsible. The younger ones accept this, while the older ones refuse, but Priestley's message is that they all share the blame for how their actions harmed one vulnerable person." },
      { g: 8, marks: 5, q: "Evaluate how Priestley presents the theme of social responsibility.", scheme: ["The Inspector voices it directly (final speech)", "Contrasted with Birling's selfishness", "Shown through the chain of events harming Eva", "Judgement on how effectively"], answer: "Priestley presents social responsibility mainly through the Inspector, whose final speech directly urges collective responsibility, contrasted with Mr Birling's selfishness. The chain of events showing how each character harmed Eva powerfully demonstrates the message, so Priestley presents the theme very effectively." },
      { g: 8, marks: 5, q: "'Sheila and Eric represent hope for the future.' Evaluate this view.", scheme: ["Both accept responsibility and are changed", "Contrast with the unchanged older Birlings", "But Gerald (young) does not change", "Balanced judgement"], answer: "Sheila and Eric strongly support this view, as both accept their guilt and are genuinely changed, unlike their parents. However, the younger Gerald tries to explain everything away, so Priestley places hope in some, but not all, of the younger generation." },
      { g: 8, marks: 4, q: "Analyse how Priestley criticises class division in the play.", scheme: ["The wealthy Birlings exploit and look down on Eva", "Mrs Birling's snobbery", "The Inspector challenges class prejudice", "Judgement"], answer: "Priestley criticises class division through the way the wealthy Birlings exploit and look down on the working-class Eva, especially in Mrs Birling's snobbery, while the Inspector directly challenges their prejudice and insists all people matter equally." },
      { g: 8, marks: 5, q: "Evaluate how Priestley uses the Inspector to convey his socialist message.", scheme: ["The Inspector is Priestley's mouthpiece", "His final speech states the message directly", "His moral authority makes it convincing", "Judgement on effectiveness"], answer: "Priestley uses the Inspector as his mouthpiece to convey socialism: his interrogations expose the harm caused by selfishness, and his powerful final speech states the message of collective responsibility directly. His moral authority makes this message compelling, so the Inspector is an effective vehicle for Priestley's views." },
      { g: 8, marks: 4, q: "Analyse how gender inequality is presented in the play.", scheme: ["Eva exploited as a poor woman (by Gerald, Eric)", "Women seen as dependent/vulnerable", "Sheila's privilege vs Eva's powerlessness", "Judgement"], answer: "Priestley presents gender inequality through Eva, who is exploited by Gerald and Eric because she is a poor woman with no power, and by contrasting her vulnerability with Sheila's privilege. This exposes how women, especially poor women, were treated as dependent and disposable." },
      { g: 8, marks: 5, q: "'Mr Birling is presented as a foolish man.' How far do you agree?", scheme: ["Dramatic irony (Titanic, war) makes him look foolish", "Selfish, arrogant, unable to learn", "But he is also powerful and dangerous", "Balanced judgement"], answer: "Mr Birling is largely presented as foolish, undermined by dramatic irony about the Titanic and war and by his refusal to learn. However, he is also powerful and influential, so Priestley presents him as dangerous as well as foolish — a man whose selfish views have real consequences." },
      { g: 8, marks: 4, q: "Analyse how Priestley creates dramatic impact in the play.", scheme: ["The Inspector's gradual revelations and interrogation", "Cliffhangers and the final twist", "Conflict within the family", "Judgement"], answer: "Priestley creates dramatic impact through the Inspector's gradual, controlled revelations, cliffhangers and the shocking final twist of the phone call, as well as the escalating conflict within the family, all of which keep the audience gripped and drive home the message." },
      { g: 8, marks: 4, q: "Evaluate how the ending affects the play's message.", scheme: ["The twist (a real inspector coming) reinforces the warning", "Suggests they get a second chance to learn", "Punishes those who refused to change", "Judgement"], answer: "The ending powerfully reinforces the message: the revelation that a real inspector is coming suggests the family is being given a second chance to learn responsibility, while dramatically punishing those, like the older Birlings, who refused to change, making Priestley's warning inescapable." },
      // GRADE 9
      { g: 9, marks: 6, q: "'An Inspector Calls is a warning to its audience.' Evaluate this view.", scheme: ["The Inspector's final speech warns of consequences", "Set 1912, written 1945 — hindsight of two wars", "Urges the audience to choose responsibility over selfishness", "Some characters heed it, others don't", "Considers how effectively it warns", "Supported judgement"], answer: "The play is strongly a warning: the Inspector's final speech threatens 'fire and blood and anguish' if lessons aren't learned, and setting the play in 1912 for a 1945 audience uses the hindsight of two world wars to urge them to choose responsibility over selfishness. Through the contrast between the changed younger characters and the unchanged older ones, Priestley warns his audience effectively to build a fairer society." },
      { g: 9, marks: 6, q: "Evaluate how Priestley uses the play to criticise capitalism and class.", scheme: ["Mr Birling embodies selfish capitalism, made foolish", "Eva exploited and destroyed by the wealthy", "Mrs Birling's snobbery", "The Inspector offers a socialist alternative", "1912 vs 1945 context", "Supported judgement"], answer: "Priestley criticises capitalism and class through Mr Birling, whose selfish views are discredited by dramatic irony, and through the exploitation of the working-class Eva by each wealthy character, including the snobbish Mrs Birling. The Inspector offers a socialist alternative of collective responsibility, and the contrast between 1912 attitudes and 1945 hopes makes the criticism powerful and clear." },
      { g: 9, marks: 6, q: "'The younger generation offer hope for the future.' Assess this view.", scheme: ["Sheila and Eric accept responsibility and change", "They challenge their parents", "But Gerald resists change", "Suggests hope lies with the young, if they choose it", "Supported judgement"], answer: "There is strong support for this view, as Sheila and Eric accept their guilt, are genuinely changed and challenge their parents' refusal to learn. However, the younger Gerald sides with the older generation, so Priestley suggests hope lies with the young only if they choose responsibility, making the younger generation a source of hope but not a guarantee." },
      { g: 9, marks: 6, q: "Evaluate the Inspector as Priestley's mouthpiece.", scheme: ["Voices Priestley's socialist message directly", "Moral authority and control over the family", "His name/knowledge suggest a supernatural role", "Some argue this makes him unrealistic", "But it strengthens the message", "Supported judgement"], answer: "The Inspector is an effective mouthpiece for Priestley: he voices the socialist message of collective responsibility directly, controls the family with moral authority, and his name 'Goole' and uncanny knowledge suggest a supernatural, judge-like role. Although this makes him unrealistic, it strengthens rather than weakens the message, making him a powerful vehicle for Priestley's views." },
      { g: 9, marks: 6, q: "Assess how far An Inspector Calls can be considered a morality play.", scheme: ["The Inspector acts as a moral judge", "Each character's 'sin' is examined", "Teaches a moral lesson to the audience", "But it also has realistic drama/character", "Supported judgement"], answer: "The play strongly resembles a morality play: the Inspector acts as a moral judge examining each character's 'sin' against Eva, and the whole play teaches the audience the moral lesson of social responsibility. However, it also contains realistic drama and character development, so it is best seen as a modern morality play that combines a clear moral message with believable human conflict." },
      { g: 9, marks: 6, q: "Evaluate how Priestley presents responsibility as a collective duty.", scheme: ["The chain of events shows all contributed to Eva's death", "'We are members of one body'", "Individual selfishness harms the vulnerable", "Contrast between those who accept and reject it", "Supported judgement"], answer: "Priestley presents responsibility as a collective duty through the chain of events in which every character contributes to Eva's death, and through the Inspector's insistence that 'we are members of one body'. By showing how individual selfishness harms the vulnerable and contrasting those who accept responsibility with those who reject it, Priestley makes collective responsibility the central moral of the play." },
      { g: 9, marks: 6, q: "'The play is as relevant today as it was in 1945.' Assess this view.", scheme: ["Themes of inequality, responsibility, exploitation still relevant", "Class and gender injustice continue", "The warning about selfishness remains", "But some context (1912/1945) is dated", "Supported judgement"], answer: "The play remains highly relevant: its themes of inequality, exploitation and social responsibility still resonate, as class and gender injustice continue and the warning against selfishness applies to modern society. Although its specific 1912 and 1945 contexts are dated, its central message about how we treat one another is timeless, so the view is largely convincing." },
      { g: 9, marks: 6, q: "Evaluate how Priestley uses dramatic techniques to convey his message.", scheme: ["Dramatic irony discredits Birling", "The Inspector's gradual revelations build tension", "Cliffhangers and the final twist", "Stage directions (lighting) and structure", "Supported judgement"], answer: "Priestley uses dramatic techniques skilfully to convey his message: dramatic irony discredits Birling's views, the Inspector's gradual revelations and cliffhangers build tension, and the final twist enforces the warning, while stage directions such as the lighting shift the mood. These techniques together make the message of responsibility compelling and memorable." },
      { g: 9, marks: 6, q: "Assess how far each character deserves blame for Eva's death.", scheme: ["Each added a link in the chain (Birling, Sheila, Gerald, Mrs Birling, Eric)", "Some acted more cruelly (Mrs Birling)", "Some showed some kindness (Gerald)", "Priestley's point: all share the blame", "Supported judgement"], answer: "Each character deserves some blame, having added a link in the chain that led to Eva's death, though some acted more cruelly, like Mrs Birling refusing her charity, while others, like Gerald, showed some kindness. Priestley's point is that they all share responsibility, so rather than blaming one person the play insists on collective guilt." },
      { g: 9, marks: 6, q: "Evaluate the significance of the play's ending.", scheme: ["The twist (real inspector coming) reinforces the warning", "Suggests a second chance / cyclical structure", "Exposes those who refused to learn", "Leaves the audience with the message", "Supported judgement"], answer: "The ending is highly significant: the revelation that a real inspector is arriving reinforces the warning and suggests the family is being given a second chance in an almost cyclical structure. It exposes the older Birlings, who learned nothing, and leaves the audience with Priestley's message ringing in their ears, making the ending crucial to the play's impact." },
    ],

    "Macbeth": [
      // GRADE 4
      { g: 4, marks: 1, q: "Who wrote Macbeth?", scheme: ["William Shakespeare"], answer: "William Shakespeare." },
      { g: 4, marks: 1, q: "What is Macbeth's title at the start of the play?", scheme: ["Thane of Glamis"], answer: "Thane of Glamis." },
      { g: 4, marks: 1, q: "What do the witches prophesy Macbeth will become?", scheme: ["Thane of Cawdor and then King"], answer: "Thane of Cawdor and then King of Scotland." },
      { g: 4, marks: 1, q: "Who does Macbeth murder to become king?", scheme: ["King Duncan"], answer: "King Duncan." },
      { g: 4, marks: 1, q: "Who persuades Macbeth to kill Duncan?", scheme: ["Lady Macbeth"], answer: "Lady Macbeth." },
      { g: 4, marks: 1, q: "Who is Macbeth's friend whose descendants are prophesied to be kings?", scheme: ["Banquo"], answer: "Banquo." },
      { g: 4, marks: 1, q: "Who finally kills Macbeth?", scheme: ["Macduff"], answer: "Macduff." },
      { g: 4, marks: 1, q: "What appears to Macbeth at the banquet?", scheme: ["Banquo's ghost"], answer: "The ghost of Banquo." },
      { g: 4, marks: 1, q: "What is Lady Macbeth seen doing in her sleep near the end?", scheme: ["Sleepwalking and washing imagined blood from her hands"], answer: "Sleepwalking and trying to wash imagined blood from her hands." },
      { g: 4, marks: 1, q: "Which theme is shown by Macbeth's desire for power?", scheme: ["Ambition"], answer: "Ambition." },
      // GRADE 5
      { g: 5, marks: 2, q: "Describe how Macbeth is presented at the start of the play.", scheme: ["A brave, loyal soldier ('brave Macbeth')", "Admired by Duncan"], answer: "As a brave, loyal soldier — called 'brave Macbeth' — admired by King Duncan for his courage in battle." },
      { g: 5, marks: 1, q: "Describe the role of the witches in the play.", scheme: ["They prophesy and tempt Macbeth; represent the supernatural/evil"], answer: "They deliver the prophecies that tempt Macbeth and represent the supernatural, evil forces in the play." },
      { g: 5, marks: 2, q: "Describe Lady Macbeth's character early in the play.", scheme: ["Ambitious and ruthless", "Manipulative — questions Macbeth's manhood"], answer: "She is ambitious, ruthless and manipulative, questioning Macbeth's manhood to push him into murdering Duncan." },
      { g: 5, marks: 2, q: "Describe how guilt affects Macbeth after the murder.", scheme: ["Hallucinations (dagger, Banquo's ghost)", "Cannot sleep; paranoid"], answer: "Guilt causes Macbeth to hallucinate a dagger and Banquo's ghost, and he becomes unable to sleep and increasingly paranoid." },
      { g: 5, marks: 2, q: "Describe how guilt affects Lady Macbeth by the end.", scheme: ["Sleepwalking and madness", "Obsessive hand-washing; suicide"], answer: "She descends into madness, sleepwalking and obsessively washing imagined blood from her hands, and eventually takes her own life." },
      { g: 5, marks: 1, q: "Describe the significance of the dagger Macbeth 'sees'.", scheme: ["A hallucination symbolising his guilt/ambition leading him to murder"], answer: "It is a hallucination symbolising his guilt and ambition leading him towards the murder." },
      { g: 5, marks: 2, q: "Describe how Macbeth changes over the course of the play.", scheme: ["From a brave, honourable hero", "To a paranoid, murderous tyrant"], answer: "He changes from a brave, honourable hero into a paranoid, murderous tyrant." },
      { g: 5, marks: 2, q: "Describe the idea of the divine right of kings in the play.", scheme: ["Kings are chosen by God", "So murdering Duncan is a sin against God and nature"], answer: "The belief that a king is chosen by God, so killing Duncan is a sin against God and the natural order." },
      { g: 5, marks: 2, q: "Describe how the natural order is disturbed after Duncan's murder.", scheme: ["Unnatural events (darkness, horses eating each other)", "Reflect the disorder caused"], answer: "Unnatural events occur — darkness in daytime, horses eating each other — reflecting how killing the king has disturbed the natural order." },
      { g: 5, marks: 1, q: "Describe Macduff's role in the play.", scheme: ["A loyal noble who kills Macbeth and helps restore order"], answer: "He is a loyal noble who kills Macbeth and helps restore rightful order to Scotland." },
      // GRADE 6
      { g: 6, marks: 3, q: "Explain how Shakespeare presents Macbeth's ambition.", scheme: ["'Vaulting ambition' drives him to murder", "Soliloquies reveal his desire for power", "Ambition overrides his conscience"], answer: "Shakespeare shows Macbeth's 'vaulting ambition' driving him to murder, using soliloquies to reveal his desire for power, which overrides his conscience and destroys him." },
      { g: 6, marks: 3, q: "Explain how the witches influence Macbeth.", scheme: ["Their prophecies plant/encourage his ambition", "Equivocation (misleading truths)", "They give him false confidence"], answer: "The witches' prophecies plant and fuel Macbeth's ambition, and their equivocal, half-true predictions later give him false confidence, encouraging his downfall." },
      { g: 6, marks: 3, q: "Explain how Lady Macbeth manipulates Macbeth into killing Duncan.", scheme: ["Questions his masculinity/calls him a coward", "Plans the murder", "Uses emotional pressure"], answer: "She questions his manhood, calls him a coward, plans the murder and steadies his nerve, using emotional pressure to push him into killing Duncan." },
      { g: 6, marks: 3, q: "Explain how the imagery of blood shows guilt.", scheme: ["Blood symbolises guilt that cannot be washed away", "Macbeth: 'great Neptune's ocean'", "Lady Macbeth: 'out, damned spot'"], answer: "Blood symbolises guilt that cannot be washed away: Macbeth feels an ocean could not clean his hands, and Lady Macbeth's cry 'out, damned spot' shows her unbearable guilt." },
      { g: 6, marks: 2, q: "Explain the significance of 'Fair is foul, and foul is fair'.", scheme: ["Introduces appearance versus reality", "Things are not what they seem"], answer: "It introduces the theme of appearance versus reality, warning that in the play things are not what they seem and good and evil are confused." },
      { g: 6, marks: 3, q: "Explain how the relationship between Macbeth and Lady Macbeth changes.", scheme: ["Early: Lady Macbeth dominant", "Later: Macbeth acts alone (Banquo)", "They grow apart as guilt destroys them"], answer: "At first Lady Macbeth dominates, but as Macbeth grows more ruthless he acts alone, such as ordering Banquo's murder, and the couple grow apart as guilt destroys them both." },
      { g: 6, marks: 3, q: "Explain the importance of the supernatural in the play.", scheme: ["Creates fear and tension", "Reflects Jacobean beliefs in witchcraft", "Drives the plot (prophecies, ghosts)"], answer: "The supernatural creates fear and tension, reflects Jacobean beliefs in witchcraft, and drives the plot through the witches' prophecies and the appearance of ghosts." },
      { g: 6, marks: 3, q: "Explain how the context of James I is relevant to Macbeth.", scheme: ["James believed in witchcraft (Daemonologie)", "Believed in the divine right of kings", "Banquo his ancestor; the Gunpowder Plot"], answer: "James I believed strongly in witchcraft and the divine right of kings, and Banquo was thought to be his ancestor, so the play, written after the Gunpowder Plot, flatters James and warns against killing a king." },
      { g: 6, marks: 3, q: "Explain how Shakespeare contrasts Duncan and Macbeth as kings.", scheme: ["Duncan: gracious, generous, rightful", "Macbeth: a tyrant ruling by fear/murder", "Contrast shows the horror of the crime"], answer: "Duncan is presented as a gracious, rightful king, while Macbeth becomes a tyrant ruling through fear and murder, and this contrast highlights the horror of Macbeth's crime and the disorder it causes." },
      { g: 6, marks: 2, q: "Explain the significance of Lady Macbeth's sleepwalking scene.", scheme: ["Reveals her suppressed guilt", "Shows her mental breakdown and downfall"], answer: "The sleepwalking scene reveals the guilt Lady Macbeth had suppressed and shows her complete mental breakdown, marking her downfall." },
      // GRADE 7
      { g: 7, marks: 4, q: "Analyse how Shakespeare uses Macbeth's soliloquies to reveal his inner conflict.", scheme: ["Soliloquies show private doubts", "'Is this a dagger...' shows torment", "Conflict between ambition and conscience", "Vivid imagery of his troubled mind"], answer: "Shakespeare uses soliloquies such as 'Is this a dagger which I see before me' to expose Macbeth's private torment, revealing the conflict between his ambition and conscience through vivid imagery of his increasingly troubled mind." },
      { g: 7, marks: 4, q: "Analyse how Lady Macbeth is presented as a powerful female character.", scheme: ["Dominates Macbeth and drives the murder", "'Unsex me here' — rejects femininity", "Commanding, ruthless language", "Power collapses into guilt/madness"], answer: "Lady Macbeth is presented as powerful as she dominates Macbeth and drives the murder, asking spirits to 'unsex' her so she can be ruthless. Her commanding, manipulative language shows her strength, though this power collapses into guilt and madness." },
      { g: 7, marks: 4, q: "Analyse how the theme of appearance versus reality runs through the play.", scheme: ["'Fair is foul' sets it up", "The Macbeths hide intent ('innocent flower')", "The witches' equivocation deceives", "Deception leads to disorder"], answer: "Set up by 'fair is foul', the theme develops as the Macbeths hide murderous intent behind loyal appearances — 'look like the innocent flower' — while the witches' equivocal prophecies deceive Macbeth, so deception drives the play's disorder." },
      { g: 7, marks: 4, q: "Analyse how Shakespeare presents the consequences of unchecked ambition.", scheme: ["Ambition leads to repeated murder", "Destroys conscience, marriage, sanity", "Brings tyranny and disorder", "Both Macbeths destroyed"], answer: "Shakespeare shows unchecked ambition leading Macbeth to murder repeatedly, destroying his conscience, marriage and sanity and bringing tyranny and disorder to Scotland, until both he and Lady Macbeth are destroyed — presenting ambition as a corrupting, destructive force." },
      { g: 7, marks: 3, q: "Analyse the role of the supernatural in shaping the events of the play.", scheme: ["The witches' prophecies begin the ambition", "Apparitions give false confidence", "Ghosts and visions reflect guilt"], answer: "The supernatural shapes the play as the witches' prophecies spark Macbeth's ambition and their apparitions give him false confidence, while ghosts and visions reflect his guilt, so it both drives the plot and mirrors his moral collapse." },
      { g: 7, marks: 4, q: "Analyse how guilt destroys both Macbeth and Lady Macbeth.", scheme: ["Macbeth: hallucinations, sleeplessness, paranoia", "Lady Macbeth: sleepwalking, madness, suicide", "Their roles reverse", "Guilt as punishment"], answer: "Guilt destroys Macbeth through hallucinations, sleeplessness and paranoia, and Lady Macbeth through sleepwalking, madness and suicide. As guilt overwhelms them their roles reverse, and Shakespeare presents guilt as the inescapable punishment for their crime." },
      { g: 7, marks: 4, q: "Analyse how Shakespeare presents Macbeth as a tragic hero.", scheme: ["Begins noble and admired", "Fatal flaw of ambition", "His choices cause his downfall", "Some sympathy as he recognises his fate"], answer: "Macbeth fits the tragic hero: he begins noble and admired but has the fatal flaw of ambition, which leads him to make choices that cause his downfall. As he recognises the emptiness of what he has done, the audience feels some sympathy amid his destruction." },
      { g: 7, marks: 4, q: "Analyse how gender and masculinity are explored in the play.", scheme: ["Lady Macbeth links manhood to violence", "Manipulates Macbeth via masculinity", "Challenges expectations of women", "Macduff's compassionate manhood"], answer: "Shakespeare explores gender as Lady Macbeth links manhood to violence and manipulates Macbeth by questioning his masculinity while rejecting traditional femininity herself. This is contrasted with Macduff's compassionate grief, so the play questions what it means to be a man." },
      { g: 7, marks: 3, q: "Analyse how Shakespeare presents the theme of fate versus free will.", scheme: ["The witches predict the future (fate)", "But Macbeth chooses to act (free will)", "Ambition drives his crimes", "Leaves the question open"], answer: "Shakespeare presents the tension between fate and free will: the witches predict Macbeth's future, suggesting fate, yet he chooses to act on their words, driven by ambition, so the play leaves open how far he is doomed or responsible." },
      { g: 7, marks: 4, q: "Analyse how order is disrupted and restored in the play.", scheme: ["Killing Duncan disrupts natural/divine order", "Unnatural events and tyranny follow", "Macduff and Malcolm defeat Macbeth", "Rightful order restored"], answer: "Killing Duncan disrupts the natural and divine order, followed by unnatural events and Macbeth's tyranny, until Macduff and the rightful heir Malcolm defeat him and order is restored, reflecting the Jacobean belief that killing a king brings chaos that must be corrected." },
      // GRADE 8
      { g: 8, marks: 5, q: "'Macbeth is more villain than victim.' How far do you agree?", scheme: ["Villain: chooses to murder; becomes a tyrant", "Victim: manipulated by witches/Lady Macbeth; guilt", "His ambition is his own choice", "Balanced judgement"], answer: "Macbeth is largely a villain, choosing to murder Duncan and others and becoming a bloody tyrant, but he is also a victim, manipulated by the witches and Lady Macbeth and tormented by guilt. Since his crimes come from his own ambition, he is more villain than victim, though Shakespeare keeps some sympathy for him." },
      { g: 8, marks: 5, q: "Analyse how far Lady Macbeth is responsible for Macbeth's downfall.", scheme: ["She manipulates him and plans the murder", "But Macbeth already had ambition; acts alone later", "The witches also influence him", "Balanced judgement"], answer: "Lady Macbeth bears significant responsibility, manipulating Macbeth and planning Duncan's murder, but Macbeth already harboured ambition and later murders alone, while the witches also influence him, so responsibility is shared." },
      { g: 8, marks: 5, q: "Evaluate how Shakespeare uses the witches to explore fate and free will.", scheme: ["Witches predict the future (fate)", "But they only tempt — Macbeth chooses", "Equivocation manipulates not forces", "Judgement"], answer: "Shakespeare uses the witches to raise the question of fate, as their prophecies come true, yet they only tempt Macbeth rather than force him, and their equivocal words manipulate his choices, suggesting free will shapes his fate as much as destiny." },
      { g: 8, marks: 4, q: "Analyse how ambition is presented as destructive throughout the play.", scheme: ["Ambition leads to murder and tyranny", "Destroys conscience, relationships, sanity", "Brings disorder to Scotland", "Judgement"], answer: "Ambition is consistently destructive: it leads Macbeth to murder and tyranny, destroys his conscience, marriage and sanity, and brings disorder to Scotland, so through the ruin of both Macbeths Shakespeare presents unchecked ambition as a corrupting force." },
      { g: 8, marks: 5, q: "'Lady Macbeth is the most powerful character in the play.' Evaluate this view.", scheme: ["Early power: dominates Macbeth", "But loses power as Macbeth acts alone", "Guilt destroys her (madness/suicide)", "Balanced judgement"], answer: "Lady Macbeth is powerful early on, dominating Macbeth and driving the murder, but her power fades as Macbeth acts without her, and guilt destroys her, so her power is real but short-lived and she is not the most powerful character overall." },
      { g: 8, marks: 5, q: "Analyse how Shakespeare presents guilt and its effects on the characters.", scheme: ["Macbeth: hallucinations, sleeplessness, paranoia", "Lady Macbeth: sleepwalking, madness, suicide", "Guilt as psychological punishment", "Blood imagery; judgement"], answer: "Shakespeare presents guilt as a powerful psychological punishment: Macbeth suffers hallucinations and paranoia while Lady Macbeth is destroyed by sleepwalking, madness and suicide, and the recurring blood imagery shows guilt that cannot be washed away." },
      { g: 8, marks: 4, q: "Evaluate how the theme of kingship reflects Jacobean values.", scheme: ["Duncan/Malcolm = rightful, God-chosen kings", "Macbeth = tyrant bringing disorder", "Reflects divine right/horror of regicide", "Flatters James I"], answer: "Kingship reflects Jacobean values as Duncan and Malcolm are rightful, God-chosen kings while Macbeth's tyranny brings disorder, reinforcing the divine right of kings and the horror of regicide, and written for James I it flatters him and warns against killing a king." },
      { g: 8, marks: 4, q: "Analyse how Macbeth's character develops and what drives that change.", scheme: ["From loyal hero to paranoid tyrant", "Driven by ambition, witches, Lady Macbeth", "Guilt hardens into ruthlessness", "Judgement"], answer: "Macbeth develops from a loyal hero into a paranoid tyrant, driven by his ambition, the witches' temptation and Lady Macbeth's manipulation, as his initial guilt hardens into ruthless violence, so ambition chiefly drives his change once unleashed." },
      { g: 8, marks: 5, q: "'The supernatural controls the events of the play.' How far do you agree?", scheme: ["Prophecies trigger events; false confidence", "But Macbeth chooses to act; ambition drives him", "Human choices cause the murders", "Balanced judgement"], answer: "The supernatural strongly influences events, as the witches' prophecies trigger Macbeth's ambition and their apparitions give false confidence, but he freely chooses to murder, driven by ambition and Lady Macbeth's pressure, so the supernatural influences but does not fully control the play." },
      { g: 8, marks: 4, q: "Analyse how Shakespeare creates a sense of moral order in the play.", scheme: ["Crime is punished (both Macbeths destroyed)", "Order restored under Malcolm", "Unnatural events show nature rejecting the crime", "Judgement"], answer: "Shakespeare creates moral order by ensuring the Macbeths' crime is punished and rightful order restored under Malcolm, while unnatural events show nature rejecting the murder, conveying the message that evil brings its own downfall and order will return." },
      // GRADE 9
      { g: 9, marks: 6, q: "'Macbeth is a tragic hero destroyed by his own ambition.' Evaluate this view.", scheme: ["Noble start, fatal flaw of ambition, downfall, sympathy", "Ambition drives his crimes", "But witches and Lady Macbeth also influence", "His free choices make him responsible", "Sympathy at the end", "Supported judgement"], answer: "Macbeth fits the tragic hero, beginning noble but destroyed by the fatal flaw of ambition, which drives his crimes while keeping some sympathy in his bleak final speeches. Although the witches and Lady Macbeth influence him, it is his own choice to act on his ambition, so the view is largely convincing — a tragic hero brought down by his own ambition." },
      { g: 9, marks: 6, q: "Evaluate how far the witches, rather than Macbeth himself, are responsible for the tragedy.", scheme: ["Witches plant ambition/give false confidence", "But they only tempt", "Macbeth chooses each murder", "Lady Macbeth also responsible", "Ambiguity", "Supported judgement"], answer: "The witches share responsibility, planting Macbeth's ambition and giving false confidence, but they only tempt him and never force his actions. Macbeth freely chooses each murder, encouraged by Lady Macbeth, and Shakespeare leaves this ambiguous, so responsibility rests mainly with Macbeth, with the witches as a catalyst." },
      { g: 9, marks: 6, q: "'Lady Macbeth is a more complex character than Macbeth.' Assess this view.", scheme: ["Lady Macbeth: ruthless then guilt-ridden; rejects femininity", "Dramatic change to madness", "Macbeth also complex: conscience vs ambition", "Both richly developed", "Supported judgement"], answer: "Lady Macbeth is highly complex, moving from ruthless ambition to being destroyed by guilt, but Macbeth is arguably just as complex, torn between conscience and ambition and between guilt and tyranny. Both are richly developed, so while her transformation is striking, it is hard to say she is definitively more complex." },
      { g: 9, marks: 6, q: "Evaluate how Shakespeare uses the play to explore ideas about power and its corrupting effects.", scheme: ["Macbeth gains power by murder, corrupted into tyranny", "Power destroys conscience/relationships", "Contrast with rightful kings", "Lady Macbeth's power corrupts too", "Jacobean fears", "Supported judgement"], answer: "Shakespeare explores power as corrupting: Macbeth seizes it through murder and is corrupted into a paranoid tyrant, while Lady Macbeth's craving for power destroys her. Contrasted with the rightful kings Duncan and Malcolm, this reflects Jacobean fears about illegitimate power, showing that power taken through evil corrupts and cannot last." },
      { g: 9, marks: 6, q: "Assess how far Macbeth retains the audience's sympathy throughout the play.", scheme: ["Early sympathy: noble hero, conscience", "Falls as he murders innocents", "Some returns in his despairing speeches", "Depends on the audience", "Supported judgement"], answer: "Macbeth wins early sympathy as a noble, conscience-stricken hero, but this falls as he murders innocents like Macduff's family, before some returns in his despairing final speeches. Shakespeare keeps just enough sympathy for him to remain a tragic figure rather than a mere monster." },
      { g: 9, marks: 6, q: "Evaluate the significance of guilt as a central theme of the play.", scheme: ["Guilt tortures both Macbeths", "Blood imagery makes it inescapable", "Shows the psychological cost of their crime", "Drives Lady Macbeth to suicide", "Central to the warning", "Supported judgement"], answer: "Guilt is central to the play: it tortures Macbeth with hallucinations and destroys Lady Macbeth through madness and suicide, while recurring blood imagery shows it can never be washed away. By dramatising the psychological cost of their crime, Shakespeare makes guilt the driving force of the tragedy and the heart of its warning." },
      { g: 9, marks: 6, q: "'Order and the divine right of kings are central to the play's meaning.' Assess this view.", scheme: ["Killing Duncan causes disorder", "Unnatural events reflect broken order", "Order restored under Malcolm", "Reflects Jacobean beliefs/flatters James", "But ambition/guilt also central", "Supported judgement"], answer: "Order and divine right are clearly central: killing the God-chosen king plunges Scotland into disorder marked by unnatural events until rightful order is restored under Malcolm, reflecting Jacobean beliefs and flattering James I. However, the play is equally about ambition and guilt, so these themes shape its meaning alongside order and kingship." },
      { g: 9, marks: 6, q: "Evaluate how Shakespeare presents the relationship between ambition and masculinity.", scheme: ["Lady Macbeth links manhood to violence", "Questions Macbeth's masculinity to spur ambition", "Macbeth 'proves' manhood by murder", "Macduff's compassionate manhood", "Toxic link; supported judgement"], answer: "Shakespeare links ambition and masculinity as Lady Macbeth defines manhood through violence and questions Macbeth's masculinity to spur his ambition, so that he 'proves' his manhood through murder. Contrasted with Macduff's more compassionate manhood, this suggests equating masculinity with ruthless ambition is destructive." },
      { g: 9, marks: 6, q: "Assess how far fate determines the outcome of the play.", scheme: ["Prophecies all come true (fate)", "But Macbeth chooses to act", "Equivocation manipulates not compels", "Free will arguably greater", "Ambiguity deliberate", "Supported judgement"], answer: "Fate appears powerful, as all the prophecies come true, but Macbeth chooses to act on them, driven by ambition and Lady Macbeth, and the witches manipulate rather than compel him. Free will is arguably the greater force, and Shakespeare deliberately keeps this ambiguous, making the tension part of the tragedy." },
      { g: 9, marks: 6, q: "Evaluate how the play would have resonated with its original Jacobean audience.", scheme: ["Belief in witchcraft made the supernatural terrifying", "Divine right/regicide (Gunpowder Plot)", "Banquo as James I's ancestor flatters him", "Warns against ambition/rebellion", "Supported judgement"], answer: "The play would have resonated strongly with a Jacobean audience: their belief in witchcraft made the supernatural genuinely terrifying, and their belief in divine right and the recent Gunpowder Plot made regicide deeply shocking. Presenting Banquo as James I's ancestor flattered the king, while the Macbeths' ruin warned against ambition and rebellion." },
    ],

    "A Christmas Carol": [
      // GRADE 4
      { g: 4, marks: 1, q: "Who wrote A Christmas Carol?", scheme: ["Charles Dickens"], answer: "Charles Dickens." },
      { g: 4, marks: 1, q: "Who is the miserly main character?", scheme: ["Ebenezer Scrooge"], answer: "Ebenezer Scrooge." },
      { g: 4, marks: 1, q: "Who was Scrooge's dead business partner?", scheme: ["Jacob Marley"], answer: "Jacob Marley." },
      { g: 4, marks: 1, q: "Name the three spirits that visit Scrooge.", scheme: ["The Ghosts of Christmas Past, Present and Yet to Come"], answer: "The Ghosts of Christmas Past, Christmas Present and Christmas Yet to Come." },
      { g: 4, marks: 1, q: "Who is Scrooge's poorly paid clerk?", scheme: ["Bob Cratchit"], answer: "Bob Cratchit." },
      { g: 4, marks: 1, q: "Who is the Cratchits' sick son?", scheme: ["Tiny Tim"], answer: "Tiny Tim." },
      { g: 4, marks: 1, q: "Who is Scrooge's cheerful nephew?", scheme: ["Fred"], answer: "Fred." },
      { g: 4, marks: 1, q: "Name the two children beneath the Ghost of Christmas Present's robe.", scheme: ["Ignorance and Want"], answer: "Ignorance and Want." },
      { g: 4, marks: 1, q: "What does Scrooge say about Christmas at the start?", scheme: ["'Bah! Humbug!'"], answer: "'Bah! Humbug!'" },
      { g: 4, marks: 1, q: "When was A Christmas Carol written?", scheme: ["1843"], answer: "1843." },
      // GRADE 5
      { g: 5, marks: 2, q: "Describe how Scrooge is presented at the start of the novella.", scheme: ["Cold, mean and miserly ('tight-fisted')", "Isolated and unkind"], answer: "He is presented as a cold, mean, 'tight-fisted' miser who is isolated and unkind to everyone." },
      { g: 5, marks: 2, q: "Describe Marley's ghost's warning to Scrooge.", scheme: ["He is weighed down by chains he made in life", "Warns Scrooge to change or suffer the same fate"], answer: "Marley's ghost, weighed down by the chains he forged in life, warns Scrooge to change his ways or suffer the same fate." },
      { g: 5, marks: 2, q: "Describe what the Ghost of Christmas Past shows Scrooge.", scheme: ["His lonely childhood", "His lost love, Belle"], answer: "It shows Scrooge his lonely childhood and the love, Belle, he lost because of his greed." },
      { g: 5, marks: 2, q: "Describe what the Ghost of Christmas Present shows Scrooge.", scheme: ["The joy of Christmas despite hardship", "The poverty of the Cratchits; Ignorance and Want"], answer: "It shows Scrooge the joy of Christmas despite hardship, the Cratchits' poverty, and the warning children Ignorance and Want." },
      { g: 5, marks: 2, q: "Describe the Ghost of Christmas Yet to Come.", scheme: ["Silent and frightening", "Shows Scrooge's lonely, unmourned death"], answer: "A silent, frightening figure who shows Scrooge his own lonely, unmourned death." },
      { g: 5, marks: 1, q: "Describe how Scrooge treats Bob Cratchit at the start.", scheme: ["Underpays and overworks him; mean about coal/heating"], answer: "He underpays and overworks Bob Cratchit and is mean even about heating the office." },
      { g: 5, marks: 2, q: "Describe how Scrooge changes by the end of the novella.", scheme: ["Becomes generous and kind", "Joyful; helps the Cratchits and others"], answer: "By the end Scrooge is generous, kind and joyful, helping the Cratchits and others and celebrating Christmas." },
      { g: 5, marks: 1, q: "Describe Tiny Tim's role in the novella.", scheme: ["A symbol of the innocent, vulnerable poor ('God bless us, every one!')"], answer: "He symbolises the innocent, vulnerable poor, best remembered for saying 'God bless us, every one!'" },
      { g: 5, marks: 2, q: "Describe the children Ignorance and Want.", scheme: ["Allegorical children symbolising the neglected poor", "A warning to society"], answer: "They are allegorical children symbolising the neglected poor, shown as a warning of what happens if society ignores them." },
      { g: 5, marks: 1, q: "Describe Fred's attitude towards Scrooge and Christmas.", scheme: ["Kind and generous; keeps inviting Scrooge to celebrate"], answer: "Fred is kind and generous and keeps inviting Scrooge to celebrate Christmas despite being rejected." },
      // GRADE 6
      { g: 6, marks: 3, q: "Explain how Dickens presents Scrooge at the start using imagery.", scheme: ["Cold imagery ('solitary as an oyster', frost)", "Links his coldness to his character", "Isolated from others"], answer: "Dickens uses cold imagery, calling Scrooge 'hard and sharp as flint' and 'solitary as an oyster', linking the coldness around him to his cold, isolated character." },
      { g: 6, marks: 2, q: "Explain the purpose of Marley's ghost in the novella.", scheme: ["Warns Scrooge of the consequences of greed", "Introduces the supernatural and the three ghosts"], answer: "Marley's ghost warns Scrooge of the consequences of a greedy, selfish life and introduces the supernatural framework of the three ghosts who will visit him." },
      { g: 6, marks: 3, q: "Explain how the Ghost of Christmas Past affects Scrooge.", scheme: ["Reminds him of happier, kinder times", "Shows what his greed cost him (Belle)", "Begins to soften/reawaken his emotions"], answer: "The Ghost of Christmas Past reminds Scrooge of happier times and shows what his greed cost him, such as losing Belle, beginning to soften him and reawaken his emotions." },
      { g: 6, marks: 3, q: "Explain the message of the Ghost of Christmas Present through Ignorance and Want.", scheme: ["Warns of the dangers of ignoring the poor", "Ignorance especially dangerous", "A warning to society/the reader"], answer: "By revealing the starving children Ignorance and Want, the Ghost warns Scrooge — and the reader — of the dangers of ignoring the poor, especially Ignorance, delivering Dickens' warning to Victorian society." },
      { g: 6, marks: 2, q: "Explain how the Ghost of Christmas Yet to Come frightens Scrooge into changing.", scheme: ["Shows his lonely, unmourned death", "The fear pushes him to promise to change"], answer: "By silently showing Scrooge his own lonely, unmourned death and stolen belongings, the Ghost terrifies him into promising to change his ways." },
      { g: 6, marks: 3, q: "Explain Dickens' message about the treatment of the poor.", scheme: ["The rich have a duty to help the poor", "Shown through the Cratchits/Tiny Tim", "Warns of consequences (Ignorance and Want)"], answer: "Dickens argues the rich have a moral duty to help the poor, shown through the struggling but loving Cratchits, and warns through Ignorance and Want that neglecting the poor will bring ruin." },
      { g: 6, marks: 2, q: "Explain how Scrooge is redeemed by the end.", scheme: ["The ghosts move him to feel sympathy and fear", "He becomes generous and kind"], answer: "The three ghosts move Scrooge through memory, sympathy and fear until he is transformed into a generous, kind man — his redemption." },
      { g: 6, marks: 2, q: "Explain the significance of Tiny Tim in the novella.", scheme: ["Symbolises the innocent poor", "His possible death motivates Scrooge to change"], answer: "Tiny Tim symbolises the innocent, vulnerable poor, and the vision of his death is a key moment that motivates Scrooge to change." },
      { g: 6, marks: 2, q: "Explain how the context of Victorian poverty is relevant to the novella.", scheme: ["Many poor suffered in workhouses/on the streets", "Dickens wanted the rich to help; criticised harsh attitudes"], answer: "In Victorian Britain many poor people suffered in workhouses and on the streets, and Dickens wrote the novella to criticise harsh attitudes and urge the rich to help them." },
      { g: 6, marks: 2, q: "Explain how Dickens presents the theme of Christmas and generosity.", scheme: ["Christmas as a time of kindness and family (Fred, Cratchits)", "Contrasted with Scrooge's early meanness"], answer: "Dickens presents Christmas as a time of kindness, family and generosity, shown through Fred and the Cratchits, contrasted with Scrooge's early meanness to highlight its value." },
      // GRADE 7
      { g: 7, marks: 4, q: "Analyse how Dickens presents Scrooge's transformation.", scheme: ["Gradual change through the three ghosts", "From cold miser to generous man", "Language becomes warmer/joyful", "Shows people can change"], answer: "Dickens presents Scrooge's transformation gradually through the three ghosts, moving him from a cold miser to a generous man, with his language becoming warmer and joyful, showing Dickens' belief that people can change for the better." },
      { g: 7, marks: 4, q: "Analyse how Dickens uses the ghosts to structure the novella.", scheme: ["Marley introduces the warning", "Past, Present and Future ghosts each teach a lesson", "Structure moves Scrooge to redemption", "Frames the moral journey"], answer: "Dickens structures the novella around the ghosts: Marley introduces the warning, and the Ghosts of Christmas Past, Present and Yet to Come each teach Scrooge a lesson, moving him step by step from memory to sympathy to fear, framing his moral journey to redemption." },
      { g: 7, marks: 4, q: "Analyse how Dickens presents poverty in the novella.", scheme: ["The Cratchits: poor but loving", "Ignorance and Want as a warning", "Contrast with Scrooge's wealth", "Criticises society's neglect"], answer: "Dickens presents poverty sympathetically through the poor but loving Cratchits, and shockingly through the allegorical Ignorance and Want, contrasting both with Scrooge's wealth to criticise society's neglect of the poor." },
      { g: 7, marks: 3, q: "Analyse how Dickens uses Tiny Tim to convey his message.", scheme: ["Innocent and vulnerable — arouses sympathy", "His possible death shows the cost of neglect", "'God bless us, every one!' spreads the moral"], answer: "Dickens uses the innocent, vulnerable Tiny Tim to arouse the reader's sympathy, and his possible death shows the human cost of neglecting the poor, while his line 'God bless us, every one!' spreads the moral of compassion." },
      { g: 7, marks: 4, q: "Analyse how the theme of redemption is developed in the novella.", scheme: ["Scrooge begins beyond hope", "The ghosts awaken memory, sympathy and fear", "He changes and makes amends", "Suggests redemption is possible for anyone"], answer: "Dickens develops redemption by showing Scrooge begin seemingly beyond hope, then having the ghosts awaken his memory, sympathy and fear until he changes and makes amends, suggesting that redemption is possible even for the hardest heart." },
      { g: 7, marks: 4, q: "Analyse how Dickens presents social responsibility.", scheme: ["The rich have a duty to help the poor", "Scrooge learns this through the ghosts", "Ignorance and Want warn of neglect", "Directed at the Victorian reader"], answer: "Dickens presents social responsibility as the duty of the rich to help the poor, which Scrooge learns through the ghosts, with Ignorance and Want warning of the dangers of neglect — a message aimed directly at his Victorian readers." },
      { g: 7, marks: 3, q: "Analyse how Dickens uses the children Ignorance and Want.", scheme: ["Allegorical symbols of the neglected poor", "Shocking, frightening appearance", "A direct warning to society"], answer: "Dickens uses Ignorance and Want as shocking allegorical symbols of the neglected poor, with their frightening, wretched appearance delivering a direct warning to society about the consequences of ignoring the poor." },
      { g: 7, marks: 3, q: "Analyse how Scrooge's language changes through the novella.", scheme: ["From 'Bah! Humbug!' and cold refusals", "To warm, excited, generous language", "Reflects his inner change"], answer: "Scrooge's language changes from cold refusals and 'Bah! Humbug!' to warm, excited and generous speech by the end, and this shift in language reflects his inner transformation." },
      { g: 7, marks: 3, q: "Analyse how Dickens creates sympathy for the poor.", scheme: ["The Cratchits' love and hardship", "Tiny Tim's vulnerability", "Ignorance and Want's suffering"], answer: "Dickens creates sympathy for the poor through the loving but struggling Cratchits, the vulnerability of Tiny Tim and the shocking suffering of Ignorance and Want, moving the reader to care about their plight." },
      { g: 7, marks: 3, q: "Analyse how the Ghost of Christmas Yet to Come is presented.", scheme: ["Silent, dark and frightening (like death)", "Shows Scrooge's lonely death", "Its silence increases the terror"], answer: "Dickens presents the Ghost of Christmas Yet to Come as a silent, dark and frightening figure resembling death, showing Scrooge his lonely death, and its silence makes the terror and the warning even more powerful." },
      // GRADE 8
      { g: 8, marks: 5, q: "'Scrooge's redemption is convincing.' How far do you agree?", scheme: ["Gradual change through the ghosts makes it believable", "His fear and remorse are genuine", "But some argue it is sudden/idealised", "Balanced judgement"], answer: "Scrooge's redemption is largely convincing because Dickens shows it develop gradually through the ghosts, with genuine fear and remorse. Some argue it is sudden and idealised, but the careful stages of his change make it believable, supporting Dickens' message that people can change." },
      { g: 8, marks: 5, q: "Analyse how Dickens presents the theme of social responsibility.", scheme: ["The rich should help the poor", "Scrooge learns it; Cratchits/Tiny Tim", "Ignorance and Want as a warning", "Judgement on effectiveness"], answer: "Dickens presents social responsibility as the duty of the wealthy to help the poor, which Scrooge learns through the ghosts and the Cratchits, while Ignorance and Want warn of the consequences of neglect, making it an effective and central message." },
      { g: 8, marks: 5, q: "Evaluate how Dickens uses Scrooge to criticise Victorian society.", scheme: ["Scrooge embodies uncaring 'surplus population' attitudes", "His change models what society should do", "Criticises greed and neglect of the poor", "Judgement"], answer: "Dickens uses Scrooge to criticise Victorian society by making him embody harsh attitudes about the 'surplus population', then showing his change to model the generosity society should adopt. Through Scrooge, Dickens attacks the greed and neglect of the poor of his time." },
      { g: 8, marks: 5, q: "'The ghosts are the most important part of the novella.' Evaluate this view.", scheme: ["The ghosts drive Scrooge's change and structure", "But Scrooge's own reactions matter", "The message could exist without the supernatural", "Balanced judgement"], answer: "The ghosts are hugely important, driving Scrooge's change and structuring the novella, but Scrooge's own reactions and choices are equally vital to the message, and the theme of social responsibility exists beyond the supernatural, so the ghosts are central but not the whole of the novella." },
      { g: 8, marks: 4, q: "Analyse how Dickens presents poverty and the poor.", scheme: ["Sympathetic (Cratchits, Tiny Tim)", "Shocking (Ignorance and Want)", "Contrast with wealth", "Judgement"], answer: "Dickens presents the poor sympathetically through the loving Cratchits and vulnerable Tiny Tim and shockingly through Ignorance and Want, contrasting both with Scrooge's wealth to expose and criticise the suffering of the poor." },
      { g: 8, marks: 5, q: "Evaluate how Dickens presents the theme of redemption.", scheme: ["Scrooge changes from miser to generous man", "Redemption possible for anyone", "The ghosts enable his change", "Judgement on how convincing"], answer: "Dickens presents redemption powerfully through Scrooge's change from miser to generous man, enabled by the ghosts, showing that redemption is possible even for the hardest heart. The gradual, believable transformation makes this a convincing and hopeful central theme." },
      { g: 8, marks: 4, q: "Analyse how Scrooge changes and what causes his change.", scheme: ["From cold miser to warm and generous", "Caused by the ghosts (memory, sympathy, fear)", "His own remorse", "Judgement"], answer: "Scrooge changes from a cold miser into a warm, generous man, caused by the ghosts awakening his memory, sympathy and fear, and by his own growing remorse, so the change comes from both the supernatural visits and his own realisation." },
      { g: 8, marks: 5, q: "'Tiny Tim is central to Dickens' message.' How far do you agree?", scheme: ["Symbolises the innocent poor; arouses sympathy", "His fate motivates Scrooge", "But Ignorance and Want also key", "Balanced judgement"], answer: "Tiny Tim is very important, symbolising the innocent poor and arousing the sympathy that drives Dickens' message, and his fate motivates Scrooge's change. However, Ignorance and Want deliver the wider warning, so Tiny Tim is central but part of a broader message about the poor." },
      { g: 8, marks: 4, q: "Analyse how Dickens uses Christmas as a symbol in the novella.", scheme: ["Christmas symbolises kindness, family and generosity", "Contrasted with Scrooge's meanness", "Represents the values Dickens promotes", "Judgement"], answer: "Dickens uses Christmas as a symbol of kindness, family and generosity, contrasting it with Scrooge's early meanness, so that Christmas comes to represent the compassionate values Dickens wants his readers to adopt." },
      { g: 8, marks: 4, q: "Evaluate how Dickens creates a clear moral lesson.", scheme: ["Scrooge's redemption models good behaviour", "Warnings (Marley, Ignorance and Want)", "Simple, memorable message", "Judgement"], answer: "Dickens creates a clear moral lesson through Scrooge's redemption, which models the generosity readers should adopt, and through the warnings of Marley and of Ignorance and Want. The simple, memorable structure makes the moral of compassion and responsibility unmistakable." },
      // GRADE 9
      { g: 9, marks: 6, q: "'A Christmas Carol is a criticism of Victorian attitudes to the poor.' Evaluate this view.", scheme: ["Scrooge embodies harsh 'surplus population' attitudes", "Cratchits/Tiny Tim humanise poverty", "Ignorance and Want warn of neglect", "Scrooge's redemption models change", "Considers effectiveness", "Supported judgement"], answer: "The view is convincing: Dickens has Scrooge embody harsh Victorian attitudes about the poor, then uses the loving Cratchits and Tiny Tim to humanise poverty and the allegorical Ignorance and Want to warn of the consequences of neglect. Scrooge's redemption models the generosity Dickens wants, making the novella an effective and moving criticism of Victorian indifference to the poor." },
      { g: 9, marks: 6, q: "Evaluate how Dickens presents Scrooge's redemption.", scheme: ["Gradual, staged change through the ghosts", "Memory, sympathy then fear", "Genuine remorse and action", "Shows anyone can change", "Considers how convincing", "Supported judgement"], answer: "Dickens presents Scrooge's redemption as a gradual, staged change through the ghosts, moving him from memory to sympathy to fear until he feels genuine remorse and acts on it. This careful development makes the redemption convincing and supports Dickens' hopeful message that anyone, however hardened, can change." },
      { g: 9, marks: 6, q: "Assess how far the novella is a warning to its readers.", scheme: ["Marley's fate warns of greed", "Ignorance and Want warn of neglecting the poor", "Scrooge's lonely death as a warning", "Balanced with its message of hope", "Supported judgement"], answer: "The novella is strongly a warning: Marley's chained fate warns of greed, Ignorance and Want warn of neglecting the poor, and Scrooge's vision of a lonely death warns of the consequences of a selfish life. Balanced with its hopeful message that change is possible, it works as both a warning and an encouragement to its readers." },
      { g: 9, marks: 6, q: "Evaluate how Dickens uses the supernatural to convey his message.", scheme: ["The ghosts force Scrooge to confront his life", "Each ghost teaches a lesson", "Makes the moral vivid and memorable", "Reflects a moral/spiritual world", "Supported judgement"], answer: "Dickens uses the supernatural effectively: the ghosts force Scrooge to confront his past, present and future, each teaching a lesson that drives his change, making the moral vivid and memorable. The ghosts also reflect a moral universe in which selfishness has consequences, strengthening Dickens' message." },
      { g: 9, marks: 6, q: "Assess the importance of social responsibility as a theme in the novella.", scheme: ["Central message: the rich must help the poor", "Shown through Scrooge, the Cratchits, Ignorance and Want", "Reflects Dickens' own concerns", "Considers other themes (redemption)", "Supported judgement"], answer: "Social responsibility is the central theme, as Dickens argues the rich must help the poor, shown through Scrooge's change, the Cratchits and the warning of Ignorance and Want, reflecting his own concern for the poor. While redemption and Christmas are also important, they serve this central message, making social responsibility the heart of the novella." },
      { g: 9, marks: 6, q: "Evaluate how Dickens presents poverty and want.", scheme: ["Sympathetic (Cratchits, Tiny Tim)", "Shocking allegory (Ignorance and Want)", "Contrast with wealth", "Aimed at moving the reader to act", "Supported judgement"], answer: "Dickens presents poverty both sympathetically, through the loving but struggling Cratchits and vulnerable Tiny Tim, and shockingly, through the wretched allegorical children Ignorance and Want, contrasting both with Scrooge's wealth. This dual presentation is designed to move readers to feel and to act, making it a powerful depiction of poverty and want." },
      { g: 9, marks: 6, q: "'Scrooge is a symbol of the rich.' Assess this view.", scheme: ["Embodies wealthy greed and neglect", "His change models what the rich should do", "But he is also an individual character", "Considers Dickens' wider purpose", "Supported judgement"], answer: "Scrooge is strongly a symbol of the rich, embodying their greed and neglect of the poor, and his change models the generosity Dickens wants from the wealthy. However, he is also a developed individual character, so he works both as a symbol of the rich and as a person whose personal redemption gives Dickens' message emotional power." },
      { g: 9, marks: 6, q: "Evaluate how far Dickens presents change as possible for everyone.", scheme: ["Scrooge, the hardest heart, changes", "Suggests hope for anyone", "The ghosts enable it", "But Marley is beyond change (a warning)", "Supported judgement"], answer: "Dickens strongly suggests change is possible for everyone by redeeming even Scrooge, the hardest of hearts, implying there is hope for anyone. However, Marley's fate shows change must come in life, not after death, so Dickens presents redemption as possible for all who choose it while they still can." },
      { g: 9, marks: 6, q: "Assess how Dickens uses structure to convey redemption.", scheme: ["Five 'staves' framing the journey", "Marley's warning, then Past/Present/Future", "Cyclical return to Christmas morning transformed", "Structure mirrors moral progress", "Supported judgement"], answer: "Dickens uses the five-'stave' structure to convey redemption: Marley's warning is followed by the Ghosts of Past, Present and Future, each advancing Scrooge's change, before a cyclical return to Christmas morning finds him transformed. This carefully staged structure mirrors his moral progress and makes the redemption clear and satisfying." },
      { g: 9, marks: 6, q: "Evaluate the relevance of the novella's message today.", scheme: ["Poverty and inequality still exist", "The call to care for others remains", "Redemption and generosity are timeless", "Some context (Victorian) is dated", "Supported judgement"], answer: "The novella's message remains highly relevant, as poverty and inequality still exist and its call to care for others and to be generous is timeless. Although its Victorian context is dated, its central themes of social responsibility and redemption continue to resonate, so its message is as meaningful today as when it was written." },
    ],
    "Ozymandias (Shelley)": [
      { g: 4, marks: 1, q: "Who wrote 'Ozymandias'?", scheme: ["Percy Bysshe Shelley"], answer: "Percy Bysshe Shelley." },
      { g: 4, marks: 2, q: "Give a simple summary of 'Ozymandias'.", scheme: ["A traveller describes a ruined statue", "of an ancient, powerful king in the desert"], answer: "A traveller describes the shattered ruins of a statue of a once-mighty ancient king, now broken and buried in the desert sand." },
      { g: 5, marks: 3, q: "Describe the main theme of 'Ozymandias'.", scheme: ["The impermanence of power", "Human pride/arrogance is temporary", "Nature/time outlasts rulers"], answer: "The main theme is the impermanence of human power: however proud and mighty a ruler is, time destroys everything, and only ruins remain." },
      { g: 5, marks: 3, q: "Explain the context behind 'Ozymandias'.", scheme: ["Shelley was a Romantic poet", "who distrusted tyrants and monarchy", "Based on the pharaoh Ramesses II"], answer: "Shelley was a Romantic poet who disliked tyranny and monarchy. The poem, inspired by the pharaoh Ramesses II, mocks the idea that a ruler's power can last forever." },
      { g: 6, marks: 4, q: "Explain the irony of the inscription 'Look on my Works, ye Mighty, and despair!'", scheme: ["The king boasts of his greatness", "But nothing of his works survives", "Situational irony", "His arrogance is undercut by the ruins"], answer: "The king's command to 'despair' was meant to make rivals feel hopeless before his greatness. Ironically, all that survives is a broken statue in empty desert, so the words now mock his own vanished power rather than glorifying it." },
      { g: 6, marks: 4, q: "Explain what the 'colossal wreck' and the 'lone and level sands' show.", scheme: ["The huge statue is now a wreck", "The empty desert stretches around it", "Power has crumbled to nothing", "Nature/time has won"], answer: "The 'colossal wreck' shows that even the greatest monument has decayed, while the 'lone and level sands' stretching far away show emptiness and the triumph of time and nature over human achievement." },
      { g: 7, marks: 5, q: "Analyse how Shelley uses the frame narrative (the traveller's story).", scheme: ["The story is second-hand", "distancing the once-mighty king", "His fame is reduced to a stranger's anecdote", "Emphasises how forgotten he is", "Effect on reader"], answer: "By telling the story through a traveller who saw the ruins, Shelley distances the king further from us: his power is now just a second-hand anecdote from a passing stranger. This layering shows how utterly the ruler has been forgotten and reduces his 'greatness' to a curiosity." },
      { g: 7, marks: 5, q: "Analyse how the sonnet form and irregular rhyme reflect the poem's message.", scheme: ["Sonnet usually used for love/order", "Here it is subverted", "Irregular rhyme scheme", "Mirrors the broken statue/decay", "Form reinforces theme"], answer: "Shelley uses a sonnet, a form normally linked to love and order, but subverts it: the rhyme scheme is irregular and does not follow a neat pattern. This 'broken' form mirrors the shattered statue and the collapse of the king's ordered power, so the structure itself reinforces the theme of decay." },
      { g: 8, marks: 6, q: "Evaluate how Shelley presents the impermanence of human power in 'Ozymandias'.", scheme: ["Ironic inscription", "'colossal wreck' imagery", "Frame narrative distances the king", "Subverted sonnet form", "Nature outlasts power", "Supported judgement"], answer: "Shelley presents human power as utterly impermanent. The ironic inscription, once a boast, now mocks the vanished king; the 'colossal wreck' and endless 'lone and level sands' show nature reclaiming his monument; and the frame narrative reduces his fame to a stranger's tale. The subverted sonnet form reinforces this collapse. Overall Shelley powerfully argues that no human power, however great, can survive time." },
      { g: 9, marks: 6, q: "Compare how 'Ozymandias' and 'My Last Duchess' present arrogant human power.", scheme: ["Ozymandias: power destroyed by time (irony)", "My Last Duchess: living, controlling power", "Compare methods (irony vs monologue)", "Supported comparison"], answer: "Both poems present arrogant rulers, but Shelley shows power as ultimately powerless against time, using irony and ruined imagery, while Browning shows the Duke's power as dangerously effective through the controlling dramatic monologue. Shelley mocks power's impermanence; Browning warns of its living menace." },
    ],
    "London (Blake)": [
      { g: 4, marks: 1, q: "Who wrote 'London'?", scheme: ["William Blake"], answer: "William Blake." },
      { g: 4, marks: 2, q: "Give a simple summary of 'London'.", scheme: ["The speaker walks through London", "and sees suffering and misery everywhere"], answer: "The speaker wanders through the streets of London and sees signs of poverty, suffering and oppression in everyone he meets." },
      { g: 5, marks: 3, q: "Describe the main theme of 'London'.", scheme: ["Suffering and oppression", "Abuse of power by authority", "Poverty in the city"], answer: "The main theme is the suffering caused by oppression: Blake shows how ordinary people are trapped in misery while those in power (the church, monarchy) ignore or cause it." },
      { g: 5, marks: 3, q: "Explain the context of 'London'.", scheme: ["From Songs of Experience", "Blake criticised the church, monarchy and wealthy", "Industrial, unequal London"], answer: "'London' is from Blake's 'Songs of Experience'. Blake was angry at the inequality of industrial London and criticised the church, monarchy and rich for allowing the poor to suffer." },
      { g: 6, marks: 4, q: "Explain the meaning and effect of 'mind-forg'd manacles'.", scheme: ["Manacles = chains", "'mind-forg'd' = created in the mind", "People are trapped mentally", "By oppression or their own acceptance"], answer: "'Mind-forg'd manacles' are mental chains: Blake suggests people are imprisoned not just by physical poverty but by attitudes and acceptance of oppression. The metaphor shows the suffering is created and maintained by those in power and by the people's own hopelessness." },
      { g: 6, marks: 4, q: "Explain the images of the 'blackning Church' and the 'Marriage hearse'.", scheme: ["Church blackened = moral corruption", "It ignores the suffering (chimney sweeper)", "'Marriage hearse' = marriage linked to death", "Disease/prostitution destroys families"], answer: "The 'blackning Church' suggests moral corruption and the Church's failure to help the suffering, such as the chimney sweeper. The oxymoron 'Marriage hearse' links marriage to death, implying that disease and prostitution poison love and family, so even joyful institutions are corrupted." },
      { g: 7, marks: 5, q: "Analyse the effect of the repetition of 'every' in 'London'.", scheme: ["'every' repeated many times", "Emphasises universality", "Suffering is inescapable/everywhere", "No one is spared", "Effect on reader"], answer: "The insistent repetition of 'every' ('every cry', 'every face', 'every ban') hammers home that suffering is total and inescapable: it affects every person and every street. This relentless repetition makes London feel like a trap of universal misery and pressures the reader to see the scale of the injustice." },
      { g: 7, marks: 5, q: "Analyse how structure and the first-person speaker shape 'London'.", scheme: ["Regular ABAB quatrains", "Rigid form mirrors oppression/entrapment", "First-person 'I wander' = witness", "Draws reader through the city", "Effect"], answer: "The tight, regular ABAB quatrains create a rigid, marching rhythm that mirrors the inescapable, controlled misery of the city. The first-person speaker who 'wander[s]' acts as a witness, leading the reader street by street through the suffering, which makes the criticism feel direct and personal." },
      { g: 8, marks: 6, q: "Evaluate how Blake presents the abuse of power in 'London'.", scheme: ["'mind-forg'd manacles'", "'blackning Church'", "'Marriage hearse'", "Repetition of 'every'", "Rigid structure", "Supported judgement"], answer: "Blake presents the abuse of power as pervasive and destructive. The 'mind-forg'd manacles' show people mentally enslaved, the 'blackning Church' and 'Marriage hearse' condemn corrupt institutions, and the repetition of 'every' makes the suffering universal. The rigid quatrains trap the reader in this misery. Overall Blake angrily blames those in power for the inescapable suffering of the poor." },
      { g: 9, marks: 6, q: "Compare how 'London' and 'The Charge of the Light Brigade' criticise those in power.", scheme: ["London: church/monarchy cause suffering", "Charge: leaders' fatal blunder", "Compare methods (imagery/repetition vs subtle blame)", "Supported comparison"], answer: "Both poems criticise those in power, but Blake attacks institutions for causing everyday suffering through bitter imagery and repetition, while Tennyson subtly blames leaders for a fatal military 'blunder' while still honouring the soldiers. Blake is openly angry; Tennyson's criticism is more restrained." },
    ],
    "Extract from The Prelude (Wordsworth)": [
      { g: 4, marks: 1, q: "Who wrote 'The Prelude'?", scheme: ["William Wordsworth"], answer: "William Wordsworth." },
      { g: 4, marks: 2, q: "Give a simple summary of the extract.", scheme: ["A boy takes a boat out at night", "A huge mountain frightens him"], answer: "A boy 'borrows' a rowing boat at night and rows onto a lake, but a huge, dark mountain seems to rise up and terrify him, changing his mood." },
      { g: 5, marks: 3, q: "Describe the main theme of the extract.", scheme: ["The power of nature", "Nature is greater than humans", "Humbling human pride"], answer: "The main theme is the overwhelming power of nature: the boy begins confident but nature reveals its greatness and power, humbling him and leaving him troubled." },
      { g: 5, marks: 3, q: "Explain the context of 'The Prelude'.", scheme: ["Wordsworth was a Romantic poet", "Loved and revered nature", "Autobiographical/childhood memory"], answer: "Wordsworth was a Romantic poet who revered nature as a powerful, almost spiritual force. 'The Prelude' is autobiographical, recalling a childhood experience that shaped him." },
      { g: 6, marks: 4, q: "Explain the significance of 'a huge peak, black and huge'.", scheme: ["Repetition of 'huge'", "Mountain seems alive/threatening", "Dwarfs the boy", "Shows nature's power"], answer: "The repetition of 'huge' and the darkness make the mountain seem to grow and loom over the boy, as if alive and threatening. It dwarfs him and shatters his confidence, showing nature's immense power over humans." },
      { g: 6, marks: 4, q: "Explain how the boy's mood changes during the extract.", scheme: ["Starts confident/proud", "Rowing with pride", "Becomes fearful after seeing the peak", "Left troubled/haunted"], answer: "The boy begins confident and proud, rowing strongly, but after the mountain seems to rise up he becomes fearful and returns in a 'grave and serious mood'. For days afterwards he is haunted, showing how nature humbled and disturbed him." },
      { g: 7, marks: 5, q: "Analyse Wordsworth's use of personification of nature.", scheme: ["Mountain given life ('upreared its head')", "Acts with 'purpose of its own'", "Nature as a moral force", "Punishes the boy's pride/theft", "Effect"], answer: "Wordsworth personifies the mountain, which 'upreared its head' and moves 'with purpose of its own', making nature seem a living, conscious force. It acts almost like a stern guardian punishing the boy's pride and his 'stealth' in taking the boat, presenting nature as a powerful moral presence that overwhelms him." },
      { g: 7, marks: 5, q: "Analyse the effect of the blank verse and first-person narration.", scheme: ["Blank verse = unrhymed iambic pentameter", "Natural, reflective speech", "First-person memory", "Draws reader into the experience", "Effect"], answer: "The unrhymed blank verse flows like natural, reflective speech, suiting a poem about a remembered personal experience. The first-person narration makes the fear and awe feel immediate and genuine, drawing the reader into the boy's growing terror and Wordsworth's sense of nature's power." },
      { g: 8, marks: 6, q: "Evaluate how 'The Prelude' presents the power of nature.", scheme: ["Personified mountain", "'huge peak, black and huge'", "Boy's changing mood", "Blank verse/first person", "Nature as moral force", "Supported judgement"], answer: "Wordsworth presents nature as vast, powerful and almost conscious. The personified mountain that 'upreared its head' overwhelms the confident boy, and the repetition of 'huge' conveys its scale. His mood shifts from pride to lasting fear, and the reflective blank verse makes nature feel like a moral force that humbles human arrogance. Overall the extract powerfully shows nature's dominance over humans." },
      { g: 9, marks: 6, q: "Compare how 'The Prelude' and 'Storm on the Island' present the power of nature.", scheme: ["Both show nature overpowering humans", "Prelude: sublime, humbling mountain", "Storm: violent, frightening storm", "Compare methods (personification, verbs)", "Supported comparison"], answer: "Both poems present nature as more powerful than humans, but Wordsworth shows a sublime, awe-inspiring power that humbles the boy through the personified mountain, while Heaney shows a violent, frightening power through aggressive verbs and the storm's assault. Wordsworth inspires reverence; Heaney emphasises fear and human vulnerability." },
    ],
    "My Last Duchess (Browning)": [
      { g: 4, marks: 1, q: "Who wrote 'My Last Duchess'?", scheme: ["Robert Browning"], answer: "Robert Browning." },
      { g: 4, marks: 2, q: "Give a simple summary of the poem.", scheme: ["A Duke shows a visitor a portrait", "of his late wife, whom he controlled/had killed"], answer: "A Duke shows a visitor a painting of his 'last' (dead) wife, and as he talks he reveals his jealous, controlling nature and hints that he had her killed." },
      { g: 5, marks: 3, q: "Describe the main themes of 'My Last Duchess'.", scheme: ["Power and control", "Jealousy/possessiveness", "Status and pride"], answer: "The main themes are power, control and jealousy: the Duke wants total control over his wife and is jealous that she smiled at others, valuing his status and pride above her life." },
      { g: 5, marks: 3, q: "Explain the context of 'My Last Duchess'.", scheme: ["Set in Renaissance Italy", "Based on the Duke of Ferrara", "Dramatic monologue to an envoy arranging a new marriage"], answer: "The poem is set in Renaissance Italy and based on the Duke of Ferrara. It is a dramatic monologue spoken to an envoy who is arranging the Duke's next marriage, which makes his controlling nature more chilling." },
      { g: 6, marks: 4, q: "Explain the meaning of 'I gave commands; / Then all smiles stopped together.'", scheme: ["Implies he ordered her death", "'smiles stopped' = she died/was silenced", "Casual, chilling tone", "Shows his absolute power"], answer: "The Duke says he 'gave commands' and 'all smiles stopped together', strongly implying he had the Duchess killed for smiling too freely at others. The casual, understated way he mentions it makes his absolute, ruthless power over life and death deeply chilling." },
      { g: 6, marks: 4, q: "Explain how the Duke reveals his controlling nature.", scheme: ["Objectifies her as a painting he controls", "Jealous of her smiles/blushes", "Keeps the portrait behind a curtain only he draws", "Wants total possession"], answer: "The Duke reveals his controlling nature by treating the Duchess as an object: he keeps her portrait behind a curtain that only he may draw, showing he now fully controls her image. His jealousy that she smiled and blushed at others shows he wanted to possess her completely." },
      { g: 7, marks: 5, q: "Analyse how the dramatic monologue reveals the Duke's character.", scheme: ["Only the Duke speaks", "He condemns himself unintentionally", "Reader sees more than he intends", "Reveals arrogance/menace", "Effect"], answer: "Browning uses a dramatic monologue so that only the Duke speaks, and through his own words he unintentionally condemns himself. As he boasts of controlling his wife, the reader sees his arrogance, jealousy and menace more clearly than he realises, making the poem a powerful study of a dangerous, powerful man." },
      { g: 7, marks: 5, q: "Analyse the effect of enjambment within the rhyming couplets.", scheme: ["Poem written in rhyming couplets", "Suggests control/order", "Enjambment runs the lines on", "Hides the rhyme, mirroring hidden menace", "Effect"], answer: "The poem is written in tight rhyming couplets that suggest the Duke's desire for control and order. However, enjambment runs the sentences past the line endings, hiding the rhymes so his speech sounds casual and conversational. This tension mirrors how he masks his menace beneath a smooth, controlled surface." },
      { g: 8, marks: 6, q: "Evaluate how Browning presents power and control in 'My Last Duchess'.", scheme: ["'I gave commands'", "Objectifying the portrait/curtain", "Jealousy of her smiles", "Dramatic monologue self-exposure", "Couplets and enjambment", "Supported judgement"], answer: "Browning presents power and control as sinister. The Duke's chilling 'I gave commands' implies murder, and his control of the curtained portrait shows he now fully possesses her. The dramatic monologue lets him expose his own arrogance and jealousy, while the controlled couplets, loosened by enjambment, mirror menace hidden beneath charm. Overall Browning presents a terrifying portrait of absolute male power and control." },
      { g: 9, marks: 6, q: "Compare how 'My Last Duchess' and 'Ozymandias' present arrogant power.", scheme: ["Both show arrogant, controlling rulers", "Duchess: living, dangerous power", "Ozymandias: power destroyed by time", "Compare methods (monologue vs irony)", "Supported comparison"], answer: "Both poems present arrogant rulers, but Browning's Duke wields living, dangerous power, revealed through the self-condemning dramatic monologue, whereas Shelley's Ozymandias is mocked because time has destroyed his power, shown through irony and ruined imagery. Browning warns of power's present menace; Shelley shows its ultimate emptiness." },
    ],
    "The Charge of the Light Brigade (Tennyson)": [
      { g: 4, marks: 1, q: "Who wrote 'The Charge of the Light Brigade'?", scheme: ["Alfred, Lord Tennyson"], answer: "Alfred, Lord Tennyson." },
      { g: 4, marks: 2, q: "Give a simple summary of the poem.", scheme: ["600 soldiers charge on horseback", "into deadly enemy cannon fire", "due to a mistaken order"], answer: "Because of a mistaken order, 600 cavalry soldiers charge on horseback straight into deadly enemy cannon fire; many are killed, but their bravery is honoured." },
      { g: 5, marks: 3, q: "Describe the main themes of the poem.", scheme: ["Bravery/heroism", "The futility/horror of war", "Duty and obedience"], answer: "The main themes are bravery and the futility of war: the soldiers show incredible courage and obedience, but they are sent to their deaths by a fatal mistake, highlighting war's waste." },
      { g: 5, marks: 3, q: "Explain the context of the poem.", scheme: ["Based on a real event in the Crimean War", "A miscommunicated order", "Tennyson was Poet Laureate"], answer: "The poem is based on a real, disastrous cavalry charge in the Crimean War, caused by a miscommunicated order. Tennyson, the Poet Laureate, wrote it to honour the soldiers' bravery." },
      { g: 6, marks: 4, q: "Explain the effect of 'Someone had blundered.'", scheme: ["'blundered' = made a serious mistake", "Blames the leaders", "The soldiers pay for the error", "Subtle criticism of authority"], answer: "The line 'Someone had blundered' bluntly blames the leaders for a fatal mistake that doomed the men. Placed among praise for the soldiers, it subtly criticises those in authority while showing that the ordinary soldiers were not at fault." },
      { g: 6, marks: 4, q: "Explain the effect of 'Into the valley of Death'.", scheme: ["Biblical allusion (Psalm 23)", "'Death' personified/capitalised", "They ride towards certain death", "Emphasises danger/heroism"], answer: "'Into the valley of Death' alludes to Psalm 23 and personifies Death with a capital letter, presenting the charge as a ride towards certain doom. The image emphasises the terrible danger the soldiers faced and heightens their heroism." },
      { g: 7, marks: 5, q: "Analyse how the rhythm of the poem reflects its subject.", scheme: ["Dactylic rhythm ('Half a league...')", "Imitates galloping horses", "Drives the poem forward", "Creates urgency", "Effect"], answer: "Tennyson uses a strong dactylic rhythm ('Half a league, half a league') that imitates the sound of galloping horses charging forward. This driving beat creates urgency and momentum, pulling the reader into the relentless, unstoppable charge towards the guns." },
      { g: 7, marks: 5, q: "Analyse the effect of repetition in the poem.", scheme: ["'Cannon to right... left... in front'", "Repetition of 'the six hundred'", "Emphasises overwhelming danger", "Honours the soldiers", "Effect"], answer: "The repetition of 'Cannon to right of them, / Cannon to left of them' surrounds the soldiers with danger on every side, emphasising how hopeless their position was. The repeated 'the six hundred' becomes a refrain that honours the men and keeps their sacrifice in the reader's mind." },
      { g: 8, marks: 6, q: "Evaluate how Tennyson presents both bravery and futility in the poem.", scheme: ["'Someone had blundered' (futility)", "'valley of Death' (danger)", "Dactylic rhythm (charge)", "Repetition/refrain (honour)", "Duty despite the mistake", "Supported judgement"], answer: "Tennyson presents both the bravery and the futility of war. 'Someone had blundered' exposes the pointless mistake, and the 'valley of Death' shows the deadly danger, while the galloping dactylic rhythm and the honouring refrain 'the six hundred' celebrate the soldiers' courage and obedience. Overall Tennyson admires their heroism yet quietly laments the waste of their lives." },
      { g: 9, marks: 6, q: "Compare how 'The Charge of the Light Brigade' and 'Exposure' present war.", scheme: ["Charge: heroic action, glory and blunder", "Exposure: boredom, cold, futility", "Different views of war", "Compare methods (rhythm vs pararhyme)", "Supported comparison"], answer: "Both poems show the suffering of soldiers, but Tennyson presents war as heroic and fast-moving, using driving rhythm to honour a brave charge, while Owen presents war as a slow, futile ordeal of cold and boredom, using pararhyme and the refrain 'nothing happens'. Tennyson finds glory in sacrifice; Owen finds only pointless suffering." },
    ],
    "Exposure (Owen)": [
      { g: 4, marks: 1, q: "Who wrote 'Exposure'?", scheme: ["Wilfred Owen"], answer: "Wilfred Owen." },
      { g: 4, marks: 2, q: "Give a simple summary of 'Exposure'.", scheme: ["Soldiers wait in freezing trenches", "Nothing happens but they suffer/die from the cold"], answer: "Soldiers wait in freezing trenches in WWI. Nothing much happens in battle, but they suffer and some die from the bitter cold and endless waiting." },
      { g: 5, marks: 3, q: "Describe the main themes of 'Exposure'.", scheme: ["The futility of war", "Suffering (cold, boredom)", "Nature as the enemy"], answer: "The main themes are the futility and suffering of war: the soldiers endure freezing cold and endless waiting, and it is nature, not the enemy, that seems to attack and kill them." },
      { g: 5, marks: 3, q: "Explain the context of 'Exposure'.", scheme: ["Owen was a WWI soldier", "Wrote from real trench experience", "Anti-war viewpoint"], answer: "Owen was a soldier in WWI who wrote from real experience of the trenches. 'Exposure' reflects his anti-war viewpoint, showing the grim, pointless suffering of ordinary soldiers." },
      { g: 6, marks: 4, q: "Explain the effect of the refrain 'But nothing happens.'", scheme: ["Repeated at stanza ends", "Emphasises boredom/futility", "No glory, just waiting", "Slow, hopeless mood"], answer: "The refrain 'But nothing happens' is repeated at the end of several stanzas, emphasising the boredom and futility of the soldiers' situation. There is no heroic action, only endless waiting, which creates a hopeless, monotonous mood and questions the point of the war." },
      { g: 6, marks: 4, q: "Explain how nature is presented as the enemy in 'Exposure'.", scheme: ["'merciless iced east winds that knive us'", "Weather personified as attacking", "Cold kills, not the enemy", "Nature is the real threat"], answer: "Owen presents nature as the true enemy: the 'merciless iced east winds that knive us' are personified as deliberately attacking the men. It is the cold, wind and snow, rather than enemy soldiers, that wound and kill, showing the soldiers are defeated by the pitiless weather." },
      { g: 7, marks: 5, q: "Analyse Owen's use of pararhyme (half-rhyme).", scheme: ["Pararhyme e.g. 'knive us'/'nervous'", "Creates discomfort/unease", "Sounds 'off' or unresolved", "Mirrors soldiers' suffering", "Effect"], answer: "Owen uses pararhyme, such as 'knive us' and 'nervous', where the words almost rhyme but not quite. This creates a jarring, unresolved sound that unsettles the reader, mirroring the soldiers' discomfort, unease and the sense that nothing reaches a satisfying end in their futile situation." },
      { g: 7, marks: 5, q: "Analyse how the structure of 'Exposure' reflects its meaning.", scheme: ["Regular eight-line stanzas", "Cyclical/repetitive", "Refrain reinforces stasis", "Nothing changes/progresses", "Effect"], answer: "The regular, repetitive stanzas and the recurring refrain create a cyclical structure in which nothing progresses, mirroring the soldiers' endless, static waiting. The lack of development in the structure reinforces the sense of futility, as if the men are trapped in a loop of cold and suffering with no escape." },
      { g: 8, marks: 6, q: "Evaluate how Owen presents the futility of war in 'Exposure'.", scheme: ["Refrain 'But nothing happens'", "Nature as enemy ('knive us')", "Pararhyme creates unease", "Cyclical structure", "Suffering without glory", "Supported judgement"], answer: "Owen presents war as utterly futile. The refrain 'But nothing happens' strips away any glory, leaving only boredom and waiting, while the personified 'merciless iced east winds' show the men killed by nature rather than heroic combat. The unsettling pararhyme and cyclical structure trap the reader in the soldiers' hopeless situation. Overall Owen powerfully condemns war as pointless suffering." },
      { g: 9, marks: 6, q: "Compare how 'Exposure' and 'Bayonet Charge' present the reality of war.", scheme: ["Exposure: slow suffering, cold, futility", "Bayonet Charge: sudden terror/chaos", "Both reject glory", "Compare methods", "Supported comparison"], answer: "Both poems reject the glory of war, but Owen presents its reality as a slow, freezing ordeal of futile waiting, using the refrain and pararhyme, while Hughes presents it as sudden, chaotic terror, using in medias res and violent imagery. Owen emphasises endurance and futility; Hughes emphasises panic and the collapse of patriotic ideals." },
    ],
    "Storm on the Island (Heaney)": [
      { g: 4, marks: 1, q: "Who wrote 'Storm on the Island'?", scheme: ["Seamus Heaney"], answer: "Seamus Heaney." },
      { g: 4, marks: 2, q: "Give a simple summary of the poem.", scheme: ["An island community prepares for a storm", "The storm's power frightens them"], answer: "An island community braces itself for a violent storm. Although they have prepared, the sheer power of the wind and sea leaves them fearful and feeling powerless." },
      { g: 5, marks: 3, q: "Describe the main themes of 'Storm on the Island'.", scheme: ["The power of nature", "Human fear and powerlessness", "(Possible) conflict/violence"], answer: "The main themes are the power of nature and human fear: despite preparing, the islanders are shown to be powerless against the storm, and some read a hidden political meaning about conflict." },
      { g: 5, marks: 3, q: "Explain the context of 'Storm on the Island'.", scheme: ["Heaney was a Northern Irish poet", "Island community braced for a storm", "First eight letters spell 'Stormont' (political reading)"], answer: "Heaney was a Northern Irish poet. The poem describes an island community facing a storm, but the first eight letters spell 'Stormont' (the NI parliament), suggesting a possible reading about political conflict and violence." },
      { g: 6, marks: 4, q: "Explain the effect of 'spits like a tame cat / Turned savage'.", scheme: ["Simile comparing sea to a cat", "'tame' turning 'savage'", "Nature turns suddenly violent", "Betrayal of trust"], answer: "The simile compares the sea to 'a tame cat / Turned savage', suggesting nature can suddenly become violent and dangerous. Something once familiar and harmless turns threatening, showing how quickly nature's gentle appearance can betray the islanders and reveal its power." },
      { g: 6, marks: 4, q: "Explain the meaning of 'it is a huge nothing that we fear'.", scheme: ["'huge nothing' = the invisible wind", "Fear of something they cannot see/fight", "Paradox/oxymoron", "Nature's power is overwhelming"], answer: "'It is a huge nothing that we fear' is a paradox: the wind is invisible ('nothing') yet 'huge' and terrifying. The islanders fear a force they cannot see or fight, which makes nature's power feel even more overwhelming and their own helplessness greater." },
      { g: 7, marks: 5, q: "Analyse how the confident opening changes through the poem.", scheme: ["Begins 'We are prepared'", "Confident, secure tone", "Confidence collapses as storm builds", "Ends in fear", "Effect"], answer: "The poem opens confidently with 'We are prepared', suggesting security and control. However, as the storm's power grows, this confidence collapses into fear, ending with the islanders admitting they fear a 'huge nothing'. This shift shows how easily human confidence is overturned by nature's raw power." },
      { g: 7, marks: 5, q: "Analyse Heaney's use of violent verbs and blank verse.", scheme: ["Violent verbs ('pummels', 'exploding')", "Military/violent imagery", "Blank verse = conversational", "Contrast of calm form and violent content", "Effect"], answer: "Heaney uses violent verbs such as 'pummels' and 'exploding', along with military imagery ('salvo', 'strafes'), to convey the storm as an attack. Yet he writes in conversational blank verse, so the calm, ordinary tone contrasts with the violent content, making the storm's sudden power more unsettling." },
      { g: 8, marks: 6, q: "Evaluate how Heaney presents the power of nature in 'Storm on the Island'.", scheme: ["'tame cat / Turned savage'", "'huge nothing that we fear'", "Confident opening collapses", "Violent verbs/military imagery", "Human powerlessness", "Supported judgement"], answer: "Heaney presents nature as sudden, violent and overpowering. The simile of the 'tame cat / Turned savage' shows nature's dangerous unpredictability, the paradox 'huge nothing' captures the terror of the invisible wind, and violent verbs like 'pummels' make the storm an attack. The islanders' collapsing confidence shows human powerlessness. Overall Heaney presents nature as a force humans cannot control." },
      { g: 9, marks: 6, q: "Compare how 'Storm on the Island' and 'The Prelude' present the power of nature.", scheme: ["Both: nature overpowers humans", "Storm: violent, frightening", "Prelude: sublime, humbling", "Compare methods", "Supported comparison"], answer: "Both poems show nature overpowering humans, but Heaney presents a violent, frightening power through aggressive verbs and the collapse of the islanders' confidence, while Wordsworth presents a sublime, awe-inspiring power that humbles the boy through the personified mountain. Heaney emphasises fear; Wordsworth emphasises reverence and moral awe." },
    ],
    "Bayonet Charge (Hughes)": [
      { g: 4, marks: 1, q: "Who wrote 'Bayonet Charge'?", scheme: ["Ted Hughes"], answer: "Ted Hughes." },
      { g: 4, marks: 2, q: "Give a simple summary of 'Bayonet Charge'.", scheme: ["A soldier runs across a battlefield", "in terror during an attack"], answer: "A single soldier runs across a battlefield during an attack, overwhelmed by terror and confusion as he charges towards the enemy." },
      { g: 5, marks: 3, q: "Describe the main themes of 'Bayonet Charge'.", scheme: ["The fear and chaos of war", "Reality vs patriotism", "The instinct to survive"], answer: "The main themes are the fear and chaos of war and the gap between patriotic ideals and reality: the soldier's noble reasons vanish, leaving only raw terror and the instinct to survive." },
      { g: 5, marks: 3, q: "Explain the context and opening of 'Bayonet Charge'.", scheme: ["Begins in medias res (mid-action)", "WWI setting", "Focus on one anonymous soldier"], answer: "The poem begins in medias res ('Suddenly he awoke and was running'), throwing us straight into the action of a WWI attack. Hughes focuses on one anonymous soldier to represent the universal experience of fear in battle." },
      { g: 6, marks: 4, q: "Explain the effect of 'raw-seamed hot khaki'.", scheme: ["Physical, uncomfortable imagery", "Focus on the body/reality", "Sweat and discomfort", "War is physical, not glorious"], answer: "'Raw-seamed hot khaki' focuses on the soldier's physical discomfort: his sweaty, chafing uniform. This bodily detail grounds the poem in the harsh reality of war rather than glory, emphasising the soldier's suffering and humanity in the middle of chaos." },
      { g: 6, marks: 4, q: "Explain the significance of the injured hare in the poem.", scheme: ["The hare rolls in agony", "Innocent nature caught in war", "Symbol of the soldier/victims", "War destroys innocence"], answer: "The image of the hare that 'rolled like a flame' in agony shows innocent nature being destroyed by war. It symbolises the soldier and all victims caught up in violence, emphasising how war senselessly destroys innocent life and mirrors the soldier's own suffering." },
      { g: 7, marks: 5, q: "Analyse how Hughes uses in medias res and enjambment.", scheme: ["Opens mid-action ('Suddenly')", "Throws reader into chaos", "Enjambment creates breathless pace", "Mirrors panic/confusion", "Effect"], answer: "By opening in medias res with 'Suddenly he awoke and was running', Hughes throws the reader straight into the chaos with no context, mirroring the soldier's disorientation. Frequent enjambment creates a breathless, stumbling pace that imitates his panic and the confusion of the charge." },
      { g: 7, marks: 5, q: "Analyse how patriotism is presented ('King, honour, human dignity... / Dropped like luxuries').", scheme: ["Patriotic ideals listed", "'Dropped like luxuries'", "Ideals become worthless in fear", "Reality replaces propaganda", "Effect"], answer: "Hughes lists patriotic ideals such as 'King, honour, human dignity' and says they 'Dropped like luxuries', suggesting that in the terror of battle these grand ideas become worthless and are abandoned. This shows how the reality of fear strips away the patriotic propaganda that sent the soldier to war." },
      { g: 8, marks: 6, q: "Evaluate how Hughes presents the reality of war in 'Bayonet Charge'.", scheme: ["In medias res opening", "'raw-seamed hot khaki'", "Injured hare imagery", "'Dropped like luxuries'", "Enjambment/chaotic pace", "Supported judgement"], answer: "Hughes presents war as terrifying, physical and stripped of glory. The in medias res opening and enjambment plunge us into chaos and panic, physical details like 'raw-seamed hot khaki' emphasise bodily suffering, and the dying hare shows war destroying innocence. When patriotic ideals are 'Dropped like luxuries', Hughes reveals the gap between propaganda and the reality of fear. Overall he presents war as brutal and dehumanising." },
      { g: 9, marks: 6, q: "Compare how 'Bayonet Charge' and 'Remains' present a soldier's experience.", scheme: ["Bayonet Charge: fear in the moment", "Remains: guilt/trauma after killing", "Both reject glory", "Compare methods", "Supported comparison"], answer: "Both poems present war as damaging, but Hughes focuses on the terror of the moment of action, using in medias res and chaotic imagery, while Armitage focuses on the lasting guilt and trauma after killing, using a colloquial monologue and repetition. Hughes shows immediate fear; Armitage shows the psychological aftermath." },
    ],
    "Remains (Armitage)": [
      { g: 4, marks: 1, q: "Who wrote 'Remains'?", scheme: ["Simon Armitage"], answer: "Simon Armitage." },
      { g: 4, marks: 2, q: "Give a simple summary of 'Remains'.", scheme: ["A soldier helps shoot a looter", "and is later haunted by guilt"], answer: "A soldier helps shoot a suspected looter and, back home, is tormented by the memory and guilt, unable to escape what he did." },
      { g: 5, marks: 3, q: "Describe the main themes of 'Remains'.", scheme: ["Guilt", "The psychological trauma (PTSD) of war", "Lasting effects of conflict"], answer: "The main themes are guilt and psychological trauma: the poem shows how the act of killing haunts the soldier long after the event, presenting the lasting mental effects of war (PTSD)." },
      { g: 5, marks: 3, q: "Explain the context of 'Remains'.", scheme: ["Based on a real soldier's account", "Modern conflict (e.g. Iraq)", "Part of a war poetry project"], answer: "'Remains' is based on a real soldier's testimony about a modern conflict (linked to Iraq), written for a poetry project about war. This gives it a realistic, first-hand feel and highlights the effects of modern warfare on soldiers." },
      { g: 6, marks: 4, q: "Explain the effect of 'his bloody life in my bloody hands'.", scheme: ["Double meaning of 'bloody'", "Literal blood and swearing/guilt", "Allusion to Macbeth", "Guilt cannot be washed away"], answer: "'His bloody life in my bloody hands' has a double meaning: 'bloody' is both literal blood and an expression of anger and guilt. It alludes to Lady Macbeth's guilt-stained hands, suggesting the soldier feels responsible for a death he cannot wash away, showing his deep and lasting guilt." },
      { g: 6, marks: 4, q: "Explain the significance of 'probably armed, possibly not'.", scheme: ["Uncertainty about the looter", "He may have killed an innocent", "This uncertainty haunts him", "Increases the guilt"], answer: "'Probably armed, possibly not' shows the soldier's uncertainty about whether the man was a real threat. The possibility that he killed an unarmed, innocent person haunts him, and this doubt increases his guilt and torment, making the memory impossible to resolve." },
      { g: 7, marks: 5, q: "Analyse the effect of the colloquial, monologue voice.", scheme: ["Casual, everyday language ('legs it', 'sort of')", "Monologue like real speech", "Casual tone vs horrific content", "Makes trauma more shocking/real", "Effect"], answer: "Armitage uses a colloquial monologue with casual phrases like 'legs it' and 'sort of', making the soldier sound like an ordinary person telling his story. This everyday tone clashes with the horrific content, making the trauma feel more real and shocking, and drawing the reader into his experience." },
      { g: 7, marks: 5, q: "Analyse how the poem shows trauma following the soldier home.", scheme: ["Shift from warzone to home", "Memory keeps returning", "'his bloody life...' repeated", "Present tense/flashbacks", "Effect"], answer: "The poem shifts from the warzone to the soldier's home, but the memory follows him: 'he's here in my head when I close my eyes'. The repetition of 'his bloody life in my bloody hands' shows the memory returning like a flashback, conveying how the trauma of war cannot be left behind." },
      { g: 8, marks: 6, q: "Evaluate how Armitage presents the effects of conflict on a soldier.", scheme: ["Guilt ('bloody hands', Macbeth allusion)", "Uncertainty ('probably armed, possibly not')", "Colloquial monologue", "Trauma follows him home", "Repetition/flashbacks", "Supported judgement"], answer: "Armitage presents conflict as psychologically devastating. The guilt of 'his bloody life in my bloody hands' and the Macbeth allusion show the soldier cannot wash away his responsibility, while 'probably armed, possibly not' shows haunting uncertainty. The colloquial monologue makes his trauma feel real, and repetition shows the memory returning as flashbacks. Overall Armitage powerfully presents the lasting mental damage of war." },
      { g: 9, marks: 6, q: "Compare how 'Remains' and 'War Photographer' present the effects of witnessing violence.", scheme: ["Remains: guilt/trauma of the killer", "War Photographer: haunted witness", "Both show lasting effects", "Compare methods", "Supported comparison"], answer: "Both poems present the lasting effects of witnessing violence, but Armitage shows the guilt and trauma of a soldier who killed, using a colloquial monologue and repetition, while Duffy shows a photographer haunted by images and troubled by public indifference, using ordered stanzas and contrast. Both show that violence leaves permanent psychological scars." },
    ],
    "Poppies (Weir)": [
      { g: 4, marks: 1, q: "Who wrote 'Poppies'?", scheme: ["Jane Weir"], answer: "Jane Weir." },
      { g: 4, marks: 2, q: "Give a simple summary of 'Poppies'.", scheme: ["A mother remembers her son", "who has gone to war/is gone"], answer: "A mother remembers her son leaving home, possibly for war, and reflects on her grief, love and memories after he has gone." },
      { g: 5, marks: 3, q: "Describe the main themes of 'Poppies'.", scheme: ["A mother's grief and love", "Memory", "The effects of war on families"], answer: "The main themes are a mother's grief, love and memory: the poem focuses on the emotional cost of war for those left behind, rather than on the soldier or the battlefield." },
      { g: 5, marks: 3, q: "Explain the context of 'Poppies'.", scheme: ["Contemporary poem", "Poppies symbolise remembrance", "Written from a mother's perspective"], answer: "'Poppies' is a contemporary poem written from a mother's perspective. Poppies are a symbol of remembrance for soldiers, and the poem focuses on the personal, domestic experience of loss rather than combat." },
      { g: 6, marks: 4, q: "Explain the effect of the domestic imagery ('Sellotape bandaged around my hand').", scheme: ["Everyday domestic image", "'bandaged' hints at wounds/war", "Blends home and war", "Motherly care"], answer: "The domestic image of 'Sellotape bandaged around my hand' mixes ordinary home life with the language of war ('bandaged'), blending the two worlds. It shows the mother's tender, caring actions while hinting at the wounds and injuries of war, linking her love to the conflict that takes her son." },
      { g: 6, marks: 4, q: "Explain the significance of 'released a song bird from its cage'.", scheme: ["Metaphor for letting her son go", "Freedom vs loss", "Bird = son leaving home", "Bittersweet"], answer: "'Released a song bird from its cage' is a metaphor for the mother letting her son go into the world. It captures the bittersweet mix of giving him freedom while losing him, showing the painful sacrifice a parent makes when a child leaves, possibly for war." },
      { g: 7, marks: 5, q: "Analyse how the poem blends the domestic and the military.", scheme: ["Domestic images (Sellotape, blazer)", "Military language (bandaged, dovetail, front line)", "The two worlds intertwine", "Shows personal cost of war", "Effect"], answer: "Weir constantly blends domestic images (Sellotape, ironing a blazer) with military language ('bandaged', 'reinforcements', 'the front line'). By intertwining home life and war, she shows how deeply the conflict invades a family's private world, emphasising the personal, emotional cost of war for those at home." },
      { g: 7, marks: 5, q: "Analyse the effect of the first-person voice and free verse.", scheme: ["Intimate first-person mother", "Free verse = flowing/fragmented", "Mirrors memory and grief", "Personal, emotional tone", "Effect"], answer: "The intimate first-person voice makes the mother's grief personal and moving, while the free verse, with its flowing and sometimes fragmented lines, mirrors the wandering nature of memory and the disorder of grief. Together they create a tender, emotional tone that draws the reader into her loss." },
      { g: 8, marks: 6, q: "Evaluate how Weir presents the effects of war on those left behind.", scheme: ["Domestic/military blend", "'song bird from its cage'", "Sellotape 'bandaged'", "First-person grief", "Free verse/memory", "Supported judgement"], answer: "Weir presents war's effects on families as deeply painful. By blending domestic images with military language, she shows how war invades a mother's private world, and metaphors like 'released a song bird from its cage' capture the sacrifice of letting a child go. The intimate first-person voice and flowing free verse convey raw grief and memory. Overall Weir movingly presents the lasting emotional cost of war for those left behind." },
      { g: 9, marks: 6, q: "Compare how 'Poppies' and 'War Photographer' present the effects of war away from the battlefield.", scheme: ["Poppies: mother's private grief", "War Photographer: haunted observer and indifferent public", "Both away from combat", "Compare methods", "Supported comparison"], answer: "Both poems explore war away from the battlefield, but Weir focuses on a mother's private grief and memory, using domestic imagery and an intimate voice, while Duffy focuses on a photographer's professional trauma and society's indifference, using ordered stanzas and contrast. Weir emphasises personal loss; Duffy emphasises witnessing and public apathy." },
    ],
    "War Photographer (Duffy)": [
      { g: 4, marks: 1, q: "Who wrote 'War Photographer'?", scheme: ["Carol Ann Duffy"], answer: "Carol Ann Duffy." },
      { g: 4, marks: 2, q: "Give a simple summary of 'War Photographer'.", scheme: ["A photographer develops war photos at home", "Reflects on suffering and public indifference"], answer: "A war photographer develops his photographs at home in England and reflects on the horrors he has witnessed and how little people at home seem to care." },
      { g: 5, marks: 3, q: "Describe the main themes of 'War Photographer'.", scheme: ["The horror of war", "Society's indifference", "The role/conscience of the witness"], answer: "The main themes are the horror of war and public indifference: the poem contrasts the photographer's traumatic experiences with the comfortable readers at home who quickly forget the suffering he records." },
      { g: 5, marks: 3, q: "Explain the context of 'War Photographer'.", scheme: ["Duffy knew war photographers", "Photographer develops images at home", "Comment on media and public"], answer: "Duffy was inspired by war photographers she knew. The poem shows a photographer at home developing images from warzones and criticises how the media and public briefly glance at suffering before moving on with their comfortable lives." },
      { g: 6, marks: 4, q: "Explain the effect of 'spools of suffering'.", scheme: ["Metaphor/alliteration", "Film holds images of pain", "Compresses war into rolls of film", "Emphasises scale of suffering"], answer: "'Spools of suffering' uses alliteration and metaphor to describe the rolls of film that hold images of pain. The phrase compresses the vast horror of war into small spools, emphasising how much suffering the photographer carries and how his job is to record human agony." },
      { g: 6, marks: 4, q: "Explain the significance of 'they do not care'.", scheme: ["Refers to the public/readers", "People glance and forget", "Society's indifference", "Photographer's frustration"], answer: "'They do not care' refers to the newspaper readers who glance at the photographs over breakfast and quickly forget. It highlights society's indifference to distant suffering and conveys the photographer's frustration that his dangerous, important work has little lasting impact on comfortable people at home." },
      { g: 7, marks: 5, q: "Analyse the contrast between 'Rural England' and the warzones.", scheme: ["Safe, ordered England", "vs 'running children in a nightmare heat'", "Juxtaposition", "Highlights the gap between two worlds", "Effect"], answer: "Duffy contrasts the safety of 'Rural England', where 'fields' don't explode, with warzones of 'running children in a nightmare heat'. This juxtaposition highlights the enormous gap between the comfortable world at home and the horror the photographer has witnessed, emphasising both the trauma he carries and the public's detachment." },
      { g: 7, marks: 5, q: "Analyse the effect of the ordered structure and regular stanzas.", scheme: ["Four regular six-line stanzas", "Order contrasts with chaos of war", "Mirrors his controlled, ritual-like work", "Like rows of photographs", "Effect"], answer: "The poem's four regular six-line stanzas create a sense of order that contrasts sharply with the chaos of war. This ordered structure mirrors the photographer's controlled, ritual-like process of developing images and his attempt to impose order on horror, like neat rows of photographs, even as the memories disturb him." },
      { g: 8, marks: 6, q: "Evaluate how Duffy presents the horror of war and public indifference.", scheme: ["'spools of suffering'", "'they do not care'", "Contrast England/warzone", "Religious imagery ('priest')", "Ordered structure", "Supported judgement"], answer: "Duffy presents war as horrific and the public as indifferent. Metaphors like 'spools of suffering' compress agony into film, and religious imagery (the photographer as a 'priest') suggests solemn duty, while the contrast between 'Rural England' and warzones exposes the gap between comfort and horror. The blunt 'they do not care' condemns public indifference. Overall Duffy powerfully criticises how society ignores the suffering that photographers risk their lives to record." },
      { g: 9, marks: 6, q: "Compare how 'War Photographer' and 'Remains' present the effects of witnessing conflict.", scheme: ["War Photographer: haunted, frustrated witness", "Remains: guilt of the soldier", "Both show lasting effects", "Compare methods", "Supported comparison"], answer: "Both poems present the lasting effects of witnessing conflict, but Duffy shows a photographer haunted by images and frustrated by public indifference, using ordered stanzas and contrast, while Armitage shows a soldier tormented by guilt after killing, using a colloquial monologue and repetition. Both reveal that witnessing violence leaves deep, lasting psychological effects." },
    ],
    "Tissue (Dharker)": [
      { g: 4, marks: 1, q: "Who wrote 'Tissue'?", scheme: ["Imtiaz Dharker"], answer: "Imtiaz Dharker." },
      { g: 4, marks: 2, q: "Give a simple summary of 'Tissue'.", scheme: ["The poem uses paper as a metaphor", "for the fragility and power of human life"], answer: "The poem uses different kinds of paper (documents, maps, money) as a metaphor to explore how fragile human life is and how paper controls our lives." },
      { g: 5, marks: 3, q: "Describe the main themes of 'Tissue'.", scheme: ["The fragility of human life", "The power and control of paper", "Impermanence"], answer: "The main themes are the fragility of human life and the power of paper: Dharker suggests that although paper (and life) is delicate, it controls our lives, and human power and structures are ultimately impermanent." },
      { g: 5, marks: 3, q: "Explain the context of 'Tissue'.", scheme: ["Dharker explores identity/culture", "Paper as metaphor for life", "'Tissue' = paper and human tissue"], answer: "Dharker often explores identity and what shapes our lives. The title 'Tissue' puns on paper tissue and human tissue, linking the fragile paper metaphor to the fragility of the human body and life itself." },
      { g: 6, marks: 4, q: "Explain the effect of 'Paper that lets the light shine through'.", scheme: ["Thin paper lets light through", "Fragile things can be powerful/beautiful", "Light = life/hope", "Fragility valued over solidity"], answer: "'Paper that lets the light shine through' suggests that thin, fragile paper can be more valuable and beautiful than solid things because it allows light (life, truth, hope) to pass through. Dharker implies that fragility, not solid permanence, is what gives life meaning and power." },
      { g: 6, marks: 4, q: "Explain how paper is used as a metaphor for control.", scheme: ["Maps, money, documents are paper", "Paper governs our lives", "Yet it is fragile and decays", "Human power is transient"], answer: "Dharker shows that paper controls our lives through maps, money and documents ('living tissue'), yet paper is thin and easily destroyed. This metaphor suggests that the human systems and power we build on paper are ultimately fragile and impermanent, however important they seem." },
      { g: 7, marks: 5, q: "Analyse the free verse and irregular structure of 'Tissue'.", scheme: ["Free verse, short irregular stanzas", "Mostly four-line stanzas then breaks", "Fragile, airy form", "Mirrors fragility of paper/life", "Effect"], answer: "The poem is written in free verse with short, irregular stanzas that give it a fragile, airy quality, as if the words themselves are as delicate as paper. The loosening structure and the final short line mirror the fragility and impermanence of paper and human life, reinforcing the poem's central message." },
      { g: 7, marks: 5, q: "Analyse the message about human power in 'Tissue'.", scheme: ["Buildings, money, records = human power", "All are made of/recorded on paper", "Paper decays and lets light through", "Human power is transient", "Effect"], answer: "Dharker suggests human power, such as buildings, money and official records, is bound up with paper, which is fragile and lets light through. By showing that these paper structures 'fly our lives like paper kites' and can be torn, she argues that human power and control are transient, and that life's fragility is more powerful than solid permanence." },
      { g: 8, marks: 6, q: "Evaluate how Dharker presents the fragility of human power in 'Tissue'.", scheme: ["'Paper that lets the light shine through'", "Paper controls lives (maps/money)", "'paper kites' imagery", "Free verse/fragile structure", "Fragility valued", "Supported judgement"], answer: "Dharker presents human power as fragile and impermanent. Paper controls our lives through maps, money and documents, yet it is thin and decays, so 'Paper that lets the light shine through' suggests fragility is more valuable than solid permanence. The airy free verse and loosening structure mirror this delicacy. Overall Dharker argues that human power and structures are transient, and that life's fragile beauty outlasts solid, controlling power." },
      { g: 9, marks: 6, q: "Compare how 'Tissue' and 'Ozymandias' present the impermanence of human power.", scheme: ["Tissue: paper power is fragile/transient", "Ozymandias: power destroyed by time", "Both: human power does not last", "Compare methods", "Supported comparison"], answer: "Both poems present human power as impermanent, but Dharker uses the extended metaphor of fragile paper to suggest human structures are delicate and transient, while Shelley uses irony and ruined imagery to show a mighty ruler's power destroyed by time. Dharker gently celebrates fragility; Shelley mocks arrogance, but both agree human power cannot last." },
    ],
    "The Emigree (Rumens)": [
      { g: 4, marks: 1, q: "Who wrote 'The Emigree'?", scheme: ["Carol Rumens"], answer: "Carol Rumens." },
      { g: 4, marks: 2, q: "Give a simple summary of 'The Emigree'.", scheme: ["A speaker remembers a city she left", "The city is now under tyranny but her memory stays bright"], answer: "A speaker remembers a city she left as a child. Although the city is now under tyranny or war, her bright, positive memory of it cannot be destroyed." },
      { g: 5, marks: 3, q: "Describe the main themes of 'The Emigree'.", scheme: ["The power of memory", "Identity and belonging", "Loss of a homeland"], answer: "The main themes are the power of memory and identity: despite leaving her homeland and it becoming dangerous, the speaker holds on to a bright, loving memory of the city that shapes her identity." },
      { g: 5, marks: 3, q: "Explain the context of 'The Emigree'.", scheme: ["An emigree = someone who has left their country", "The city is unnamed/universal", "Themes of exile and memory"], answer: "An 'emigree' is someone forced to leave their country. The city is deliberately unnamed so it could be any lost homeland, giving the poem a universal message about exile, memory and the way people hold on to where they come from." },
      { g: 6, marks: 4, q: "Explain the effect of the repeated word 'sunlight' in 'The Emigree'.", scheme: ["'sunlight' repeated throughout", "Symbol of bright, positive memory", "Warmth/hope", "Memory cannot be darkened"], answer: "The word 'sunlight' is repeated throughout the poem as a symbol of the speaker's bright, warm and positive memory of her city. Its repetition shows that, no matter how dark the city's present reality becomes, her hopeful memory of it 'fills' her mind and cannot be darkened by tyranny." },
      { g: 6, marks: 4, q: "Explain the effect of personifying the city ('My city takes me dancing').", scheme: ["City personified as alive/loving", "Like a friend or lover", "Memory keeps the city alive", "Intimate, affectionate bond"], answer: "Personifying the city as one that 'takes me dancing' presents it as alive, loving and almost like a companion. This shows how vividly the speaker's memory keeps the city alive and reveals the deep, affectionate bond she feels, even though the real city is lost to her." },
      { g: 7, marks: 5, q: "Analyse how memory is shown to resist oppression in the poem.", scheme: ["'They' try to control/darken the city", "Memory remains bright ('sunlight')", "Tyranny cannot destroy her memory", "Defiant tone", "Effect"], answer: "Although shadowy oppressors ('They') try to control the city and 'accuse' her, the speaker's bright memory 'lies down in front of me' and cannot be destroyed. The persistent 'sunlight' resists the darkness, giving the poem a defiant tone: memory becomes a form of resistance that tyranny cannot erase." },
      { g: 7, marks: 5, q: "Analyse the effect of the first-person voice and the unnamed city.", scheme: ["Intimate first-person memory", "City unnamed/universal", "Could be any lost home", "Personal yet universal", "Effect"], answer: "The intimate first-person voice makes the speaker's love and loss feel personal and moving, while the deliberately unnamed city makes the poem universal, so it could represent any lost homeland. This combination lets the reader share the emotion while applying its message about memory and identity to many refugees and exiles." },
      { g: 8, marks: 6, q: "Evaluate how Rumens presents the power of memory in 'The Emigree'.", scheme: ["Repeated 'sunlight'", "Personified loving city", "Memory resists oppression", "First-person/unnamed city", "Defiant tone", "Supported judgement"], answer: "Rumens presents memory as powerful and unbreakable. The repeated 'sunlight' symbolises a bright memory that tyranny cannot darken, and personifying the city that 'takes me dancing' shows how vividly memory keeps her homeland alive. Even as shadowy oppressors try to control the city, her memory resists, giving a defiant tone. The intimate yet universal voice makes this a moving tribute to how memory preserves identity and love despite exile." },
      { g: 9, marks: 6, q: "Compare how 'The Emigree' and 'Kamikaze' present memory and identity.", scheme: ["Emigree: bright memory preserves identity", "Kamikaze: memory of family draws pilot back", "Both: memory shapes identity", "Compare methods", "Supported comparison"], answer: "Both poems show memory shaping identity, but Rumens presents memory as a bright, defiant force that preserves the speaker's love for her lost homeland, using the 'sunlight' motif, while Garland presents memory of family and childhood as powerful enough to make the pilot choose life, using nature imagery and a shifting narrative voice. Both show memory as central to who we are." },
    ],
    "Checking Out Me History (Agard)": [
      { g: 4, marks: 1, q: "Who wrote 'Checking Out Me History'?", scheme: ["John Agard"], answer: "John Agard." },
      { g: 4, marks: 2, q: "Give a simple summary of the poem.", scheme: ["The speaker criticises the history he was taught", "It ignored black history and his identity"], answer: "The speaker criticises the British history he was taught in school, which focused on white British figures and ignored important black historical figures and his own Caribbean identity." },
      { g: 5, marks: 3, q: "Describe the main themes of 'Checking Out Me History'.", scheme: ["Identity", "The power of history/education", "Rebellion against oppression"], answer: "The main themes are identity and the power of history: Agard shows how controlling what history is taught can suppress identity, and the speaker rebels by reclaiming the black history that was hidden from him." },
      { g: 5, marks: 3, q: "Explain the context of 'Checking Out Me History'.", scheme: ["Agard is British-Guyanese", "Criticises Eurocentric education", "Black history was left out of the curriculum"], answer: "Agard is a British-Guyanese poet who criticises the Eurocentric education he received, in which black historical figures were ignored. The poem protests against how a one-sided history denied him knowledge of his own heritage and identity." },
      { g: 6, marks: 4, q: "Explain the effect of the Caribbean dialect and phonetic spelling.", scheme: ["Non-standard spelling ('dem tell me')", "Asserts Caribbean identity", "Rejects 'standard' English", "Act of rebellion"], answer: "Agard writes in Caribbean dialect with phonetic spelling like 'Dem tell me', which asserts his cultural identity and rejects the 'standard' English of the education system. This non-standard voice becomes an act of rebellion, reclaiming his heritage against a system that tried to erase it." },
      { g: 6, marks: 4, q: "Explain the contrast between the figures taught and those left out.", scheme: ["Taught: Nelson, Napoleon, nursery rhymes", "Left out: Toussaint, Nanny, Mary Seacole", "Trivial vs important", "Black heroes hidden"], answer: "Agard contrasts the British figures and nursery rhymes he was taught with the black heroes who were hidden, such as Toussaint L'Ouverture, Nanny of the Maroons and Mary Seacole. By mixing serious history with trivial rhymes ('dish ran away with the spoon'), he shows how his education trivialised or omitted important black history." },
      { g: 7, marks: 5, q: "Analyse how Agard uses structure (the italicised sections about black heroes).", scheme: ["Black heroes in separate italic stanzas", "Different form/rhythm", "Highlights and celebrates them", "Reclaims hidden history", "Effect"], answer: "Agard separates the sections about black heroes into distinct italicised stanzas with a different, more lyrical rhythm. This visually and rhythmically sets them apart, highlighting and celebrating figures who were hidden, and structurally 'reclaims' their history from the dismissive list of British facts, reinforcing his act of reclaiming identity." },
      { g: 7, marks: 5, q: "Analyse how the poem presents reclaiming identity ('carving out me identity').", scheme: ["'carving out me identity'", "Active, effortful verb", "Rebuilding self through true history", "Empowerment", "Effect"], answer: "The phrase 'carving out me identity' uses an active, effortful verb to show the speaker rebuilding his sense of self by discovering the true history hidden from him. It presents reclaiming identity as a powerful, deliberate act of resistance, ending the poem on a note of empowerment and self-determination." },
      { g: 8, marks: 6, q: "Evaluate how Agard presents the power of history and identity.", scheme: ["Dialect/phonetic spelling", "Contrast of taught vs hidden figures", "Italicised heroes structure", "'carving out me identity'", "Rebellion/empowerment", "Supported judgement"], answer: "Agard presents history as a powerful tool that can suppress or empower identity. The Caribbean dialect asserts his heritage and rebels against 'standard' English, while the contrast between trivial British lessons and hidden black heroes exposes a biased education. Setting the heroes in separate italic stanzas reclaims their history, and 'carving out me identity' ends the poem with empowerment. Overall Agard argues that controlling history controls identity, and reclaiming true history restores selfhood." },
      { g: 9, marks: 6, q: "Compare how 'Checking Out Me History' and 'The Emigree' present identity.", scheme: ["Checking Out Me History: reclaiming identity through history", "Emigree: identity preserved through memory", "Both defiant", "Compare methods", "Supported comparison"], answer: "Both poems present identity as something to be protected against forces that threaten it, but Agard shows identity reclaimed through discovering hidden history, using dialect and structural contrast, while Rumens shows identity preserved through bright memory of a lost homeland, using the 'sunlight' motif. Both are defiant: Agard rebels against a biased education, Rumens against tyranny." },
    ],
    "Kamikaze (Garland)": [
      { g: 4, marks: 1, q: "Who wrote 'Kamikaze'?", scheme: ["Beatrice Garland"], answer: "Beatrice Garland." },
      { g: 4, marks: 2, q: "Give a simple summary of 'Kamikaze'.", scheme: ["A Japanese suicide pilot sets off", "but turns back and is later shunned"], answer: "A Japanese kamikaze pilot sets off on a suicide mission but, moved by the beauty of the sea and memories of home, turns back. Afterwards his family and community shun him for the dishonour." },
      { g: 5, marks: 3, q: "Describe the main themes of 'Kamikaze'.", scheme: ["The conflict between duty and life/family", "Honour and shame", "The consequences of choices"], answer: "The main themes are the conflict between duty and love of life and family, and honour versus shame: the pilot chooses life over his duty, but suffers the lasting consequence of being rejected by his community." },
      { g: 5, marks: 3, q: "Explain the context of 'Kamikaze'.", scheme: ["WWII Japanese suicide pilots", "Great honour to die for the emperor", "Narrated by the pilot's daughter"], answer: "In WWII, Japanese kamikaze pilots flew suicide missions, and dying for the emperor was seen as a great honour. The poem is narrated by the pilot's daughter, giving a personal, reflective view of his choice and its consequences." },
      { g: 6, marks: 4, q: "Explain why the pilot turns back.", scheme: ["Beauty of the sea/nature", "Memories of childhood/family", "Love of life overcomes duty", "Human instinct"], answer: "The pilot turns back because the beauty of the sea and fishing boats below reminds him of his childhood and family. These memories and his love of life overcome his sense of duty, showing that a powerful human instinct to live and to cherish family wins over the pressure to die honourably." },
      { g: 6, marks: 4, q: "Explain the consequences the pilot faces after turning back.", scheme: ["Shunned by family and community", "Treated as if he did not exist", "Dishonour/shame", "Lasting isolation"], answer: "After turning back, the pilot is shunned by his family and community, who treat him 'as though he no longer existed'. Because he chose life over an honourable death, he suffers lasting shame and isolation, showing the harsh consequences of defying his society's code of honour." },
      { g: 7, marks: 5, q: "Analyse how nature imagery influences the pilot's decision.", scheme: ["Sea, fishing boats, fish imagery", "Reminders of childhood/family", "Nature = life and beauty", "Draws him back to life", "Effect"], answer: "Garland uses rich nature imagery, such as the sea, fishing boats and 'a shoal of fishes', to evoke the pilot's childhood and family. This vivid beauty represents life itself and draws him back, showing how the natural world and memory awaken his love of living and pull him away from his deadly duty." },
      { g: 7, marks: 5, q: "Analyse the effect of the daughter's narration and the shift in perspective.", scheme: ["First narrated by daughter (third person)", "Shifts to first-person plural later", "Distances the pilot", "Shows family's shame and loss", "Effect"], answer: "The poem is first narrated by the pilot's daughter in the third person, which distances him and reflects how the family cut him off. Later the voice shifts closer ('we too learned to be'), showing how the family absorbed society's shame. This shifting perspective conveys the emotional cost of his choice and the lasting damage to his family." },
      { g: 8, marks: 6, q: "Evaluate how Garland presents the conflict between duty and life in 'Kamikaze'.", scheme: ["Nature imagery draws him to life", "Memories of family", "Consequences (shunned)", "Daughter's narration/shift", "Honour vs love of life", "Supported judgement"], answer: "Garland presents the conflict between duty and life as painful and complex. Vivid nature imagery and memories of family draw the pilot back to life, showing love of living overcoming duty, but the consequence is that he is shunned 'as though he no longer existed'. The daughter's narration and shifting perspective reveal the family's shame and loss. Overall Garland suggests choosing life over honour is deeply human, yet society's rigid code punishes it cruelly." },
      { g: 9, marks: 6, q: "Compare how 'Kamikaze' and 'Poppies' present the effects of war on families.", scheme: ["Kamikaze: family shame/rejection", "Poppies: mother's grief", "Both: war damages families", "Compare methods", "Supported comparison"], answer: "Both poems present war's damaging effects on families, but Garland shows a family torn apart by shame and society's code of honour, using nature imagery and a daughter's narration, while Weir shows a mother's private grief and love, using domestic imagery and an intimate voice. Garland emphasises rejection and dishonour; Weir emphasises tender loss." },
    ],
  },
}
